"""Agente heuristico para a PTCG AI Battle Challenge (engine cabt).

Contrato (do sample oficial + guia do iniciante):
  agent(obs_dict) -> list[int]  — indices de opcoes LEGAIS de obs["select"]["option"];
  tamanho entre select.minCount e select.maxCount, SEM duplicatas, cada indice em
  [0, len(option)). Nunca estourar o tempo (fallback rapido). deck.csv = 60 Card IDs.

Arquitetura: rule-based-primeiro (a evidencia da ladder mostra rule-based dominando).
O NUCLEO de selecao (`select_indices`) garante uma jogada sempre legal e e testado offline;
a PONTUACAO (`score_options`) e heuristica e sera afinada contra o engine real.

Local vs Kaggle: no Kaggle, o pacote `cg` real vem anexado. Offline, o harness de teste
poe engine_stub/ no sys.path (stub reconstruido). O agente le prioritariamente o dict cru,
robusto a diferencas de campo.
"""
from __future__ import annotations

import os
import random
import time

try:
    from cg.api import all_card_data, to_observation_class
    _HAVE_CG = True
except Exception:  # pragma: no cover — ambiente sem cg (nem stub)
    all_card_data = lambda: {}  # noqa: E731 — fallback de uma linha, proposital
    to_observation_class = None
    _HAVE_CG = False

# --- Deck (60 Card IDs) ---
def load_deck() -> list[int]:
    """Le deck.csv sem depender do diretorio de trabalho.

    O sample oficial resolve o caminho contra o cwd e, se falhar, contra
    /kaggle_simulations/agent/. Isso quebra quando o processo roda de outro
    diretorio: MY_DECK vem vazio, a determinizacao do L1 divide por zero, e a
    busca cai silenciosamente para a L0 — sem erro nenhum aparecer. Foi pego em
    teste de pacote, onde o tempo por decisao despencou de ~1 ms para 0,2 ms.
    Por isso a primeira tentativa e relativa ao PROPRIO arquivo.
    """
    # ATENCAO: `__file__` NAO EXISTE no container. O kaggle_environments carrega
    # o agente com `exec(code_object, env)` e nao define __file__ — usar a
    # variavel direto levanta NameError no import e derruba a submissao com
    # SubmissionStatus.ERROR e nenhum log. Custou S2, S3 e S4 (08/08).
    # A ironia: esta funcao passou a usar __file__ para consertar um bug de cwd,
    # e o conserto quebrou mais do que o bug original.
    candidatos = ["deck.csv", "/kaggle_simulations/agent/deck.csv"]
    aqui = os.path.dirname(os.path.abspath(globals()["__file__"])) if "__file__" in globals() else None
    if aqui:
        candidatos.insert(0, os.path.join(aqui, "deck.csv"))
    for path in candidatos:
        try:
            with open(path, "r", encoding="utf-8") as f:
                bruto = f.read().replace(",", " ").split()
            ids = [int(x) for x in bruto if x.strip()][:60]
            if len(ids) == 60:
                return ids
        except Exception:
            continue
    return []

