# >>> TABELA_DANO_FIM

MY_DECK = load_deck()
_CARDS = all_card_data() if _HAVE_CG else {}

# Tempo maximo por jogada (a MEDIR no engine real; margem conservadora)
TIME_BUDGET_S = float(os.environ.get("PTCG_TIME_BUDGET_S", "2.0"))

# Prioridade base por tipo de opcao (maior = melhor). Heuristica — afinar no engine.
# OptionType — valores CONFERIDOS contra o enum real de cg/api.py em 2026-08-07.
# (Antes disso eram inferencia sobre episodios; ver docs/api-real.md para o
# placar dessa inferencia e os dois erros que a conferencia corrigiu.)
OPT_NUMBER = 0
OPT_YES = 1
OPT_NO = 2
OPT_CARD = 3
OPT_TOOL_CARD = 4
OPT_ENERGY_CARD = 5
OPT_ENERGY = 6
OPT_PLAY = 7
OPT_ATTACH = 8
OPT_EVOLVE = 9
OPT_ABILITY = 10
OPT_DISCARD = 11
OPT_RETREAT = 12
OPT_ATTACK = 13
OPT_END = 14
OPT_SKILL = 15
OPT_SPECIAL_CONDITION = 16

# AreaType (real): o ativo e 4, nao 0 — a suposicao anterior invertia a
# preferencia entre ativo e banco.
AREA_ACTIVE = 4
AREA_BENCH = 5

# O ATAQUE VEM DEPOIS, e o motivo é mesmo "atacar encerra o turno".
#
# Este comentario ja disse o contrario. Em 18/08 mediu-se que 46,3% dos turnos
# de pilotos 1.000+ tinham "dois ou mais ataques", e a premissa foi declarada
# insustentavel. Em 21/08 aquilo foi RETRATADO: o que se contou foram duas ou
# mais ESCOLHAS de opcao do tipo ATTACK, e escolher ATTACK abre a selecao do
# golpe (existe um OPT_SKILL separado). A escolha repetida e o MESMO ataque
# sendo navegado.
#
# A medicao que fecha, nos mesmos 1.813 episodios: cruzando escolhas de ATTACK
# por turno contra eventos de dano no ativo adversario (queda de vida no mesmo
# serial, ou ida para o descarte), a media de eventos NAO SOBE —
#
#     1 escolha -> 0,93 evento   |   2 -> 0,98   |   3+ -> 0,90
#
# Se cada escolha fosse um ataque, seria 1, 2, 3. E a unidade que fecha em 1 e
# o TURNO (190 eventos em 202 turnos atacantes = 0,94), nao a escolha (0,63).
# Ver docs/h7-dois-ataques-2026-08-21.md.
#
# A MEDICAO DIRETA nunca dependeu do motivo, e continua valendo: com ATTACK no
# topo o agente ganhava 24,7% [20,1; 29,8] do aleatorio; rebaixado para logo
# acima do fim de turno, 82,3% [77,6; 86,2]. Mesma heuristica, mesma amostra,
# ICs disjuntos. Foi por isso que a retratacao nao mexeu em nenhum numero.
#
# E o quanto rebaixar voltou a ser pergunta empirica: em 19/08 subir ATTACK e
# END para o meio da escala rendeu +1,10 e +1,03 pp no painel, com o gate
# conjuntivo passando nas duas. Ver o bloco COMPRESSAO_ATAQUE mais abaixo.
# A prioridade da HABILIDADE e ajustavel por variavel de ambiente porque ela
# esta em teste: medido em 120 partidas com o deck do Ogerpon, o agente usava a
# habilidade em so 28,5% das vezes em que ela estava disponivel, e terminava a
# partida com 3,59 energias no ativo — o Myriad Leaf Shower precisa de 3 so
# para atacar e escala 30 por energia. O motor do deck nao estava rodando.
# Subir isso as cegas e arriscado: ha habilidade que se paga (Teal Dance anexa
# e compra) e habilidade que se sabota (o Run Away Draw do Dudunsparce
# embaralha o proprio Pokemon de volta ao deck com tudo anexado).
PRIO_ABILITY = float(os.environ.get("PTCG_PRIO_ABILITY", "46.0"))

# T7 — a fronteira ATTACH x PLAY, ajustavel para poder ser MEDIDA.
#
# Contra pilotos de rating 1.000+ DO NOSSO PROPRIO ARQUETIPO, em 3.304 decisoes:
# quando eles anexam energia, escolhemos outra coisa em 52,4% (188 de 359). E o
# detalhamento diz que o erro nao e de ALVO — quando decidimos anexar,
# concordamos com o destino em 100% dos casos. E de nao decidir anexar, porque
# PLAY=55 supera ATTACH=50 e havendo carta para jogar, jogamos a carta.
#
# E os pilotos fortes NAO ordenam essas duas: na posicao dentro do turno as
# duas dao mediana 0,38 e quartis 0,14/0,62 — identicas. Eles intercalam.
#
# Ver docs/t7-attach-contra-play-2026-08-19.md (pre-registro) e
#     docs/decisoes-ogerpon-forte-2026-08-18.md (a medicao).
PRIO_ATTACH = float(os.environ.get("PTCG_PRIO_ATTACH", "50.0"))

BASE_PRIORITY = {
    OPT_EVOLVE: 62.0,
    OPT_PLAY: 55.0,
    OPT_ATTACH: PRIO_ATTACH,
    OPT_ABILITY: PRIO_ABILITY,
    OPT_ENERGY: 44.0,
    OPT_ENERGY_CARD: 42.0,
    OPT_CARD: 30.0,
    OPT_TOOL_CARD: 28.0,
    OPT_SKILL: 26.0,
    OPT_SPECIAL_CONDITION: 24.0,
    OPT_NUMBER: 20.0,
    OPT_RETREAT: 18.0,
    OPT_DISCARD: 14.0,
    OPT_ATTACK: 12.0,  # depois de esgotar o que nao encerra o turno
    OPT_YES: 12.0,
    OPT_NO: 12.0,
    OPT_END: 8.0,  # so termina o turno se nao houver mais nada
}
OTHER_PRIORITY = 10.0

# COMPRESSAO DA ESCALA DE PRIORIDADE — a descoberta de 14/08.
#
# O prior tem top-1 de ZERO nas 247 decisoes em que a jogada certa era RECUAR,
# e 6,9% nas 756 em que era passar o turno. Parecia falta de modelo. Nao e:
#
#   AUC do prior DENTRO das opcoes de recuo : 0,755
#   AUC de um especialista treinado so nelas: 0,768
#
# **O prior sabe quando recuar.** Ele so nao consegue agir. A conta:
#
#   BASE_PRIORITY[EVOLVE]  = 62,0
#   BASE_PRIORITY[RETREAT] = 18,0     diferenca de 44 pontos
#   o prior mexe no maximo   ~17      (W_PRIOR=10 x logits de -1,5 a +0,2)
#
# A heuristica por TIPO afunda o recuo num poco que o prior nao alcanca. Subir
# W_PRIOR foi testado e piora (20 da -1,28pp, 30 da -2,06pp) porque afeta TODAS
# as decisoes. Comprimir a escala e diferente: mantem a ORDEM da heuristica e
# reduz a distancia, devolvendo autoridade ao prior onde ele tem informacao.
#
# 1,0 = escala original. 0,5 = metade das distancias. 0 = todos os tipos iguais.
COMPRESSAO_PRIORIDADE = float(os.environ.get("PTCG_COMPRESSAO", "1.0"))

if COMPRESSAO_PRIORIDADE != 1.0:
    _base = min(BASE_PRIORITY.values())
    BASE_PRIORITY = {t: _base + (v - _base) * COMPRESSAO_PRIORIDADE
                     for t, v in BASE_PRIORITY.items()}
    OTHER_PRIORITY = _base + (OTHER_PRIORITY - _base) * COMPRESSAO_PRIORIDADE

# T6 — COMPRESSAO SELETIVA de ATTACK e END. A compressao acima e UNIFORME, e
# falhou: +2,03pp que encolheu para +0,91pp [-0,51; +2,32] ao triplicar a
# amostra. A medicao de 15/08 explica POR QUE, e o diagnostico e o unico do
# projeto que aponta um mecanismo em vez de um palpite.
#
# Comparando 24.549 decisoes de jogadores com rating >= 1.003 com o que o nosso
# ranking escolheria na mesma posicao:
#
#   quando eles jogam END     nosso ranking escolhe outra coisa em 100,0%
#                             (1.359 de 1.359)
#   quando eles jogam ATTACK                                     em  70,9%
#   quando eles jogam CARD / NUMBER / YES                        em   0,0%
#
# O contraste fecha o diagnostico: onde todas as opcoes tem o MESMO tipo, o
# prior decide sozinho e acerta sempre. O problema e a escala entre tipos.
#
# E a busca NAO atravessa essa escala. Em 14.926 decisoes nossas (15/08), ela
# corrige ATTACH 867 vezes e ABILITY 644 — e ATTACK 23 vezes e END 58. As
# correcoes caem monotonicamente com a distancia na BASE_PRIORITY: de PLAY (55)
# a ATTACH (50) vao 5 pontos e 867 correcoes; a ATTACK (12) vao 43 pontos e 23.
#
# Atacamos com 58% da frequencia dos 1.000+ e passamos o turno com 41%.
#
# A CONTA que fixa os valores (eles sao PRE-DEFINIDOS, nao varridos):
# o prior move ~17 pontos (W_PRIOR=10 x logits de -1,5 a +0,2). Para que ele
# tenha autoridade sobre a distancia PLAY(55) -> ATTACK(12) = 43, o que sobrar
# precisa caber em 17 — ou seja, ATTACK >= 38, que e S >= 0,68.
#
# ============================================================================
# MEDIDO EM 18-19/08, E A CONTA ACIMA ESTAVA ERRADA. Leia antes de mexer.
# ============================================================================
#
# Os dois valores foram ao painel, 10 replicas por lado cada, deck v7:
#
#   S = 0,75  +1,10 pp   IC Bonferroni(2) [+0,15; +2,05]   gate PASSA
#   S = 0,50  +1,03 pp   IC Bonferroni(2) [+0,21; +1,85]   gate PASSA
#
# O 0,50 era o CONTROLE: ele poe ATTACK em 31, VINTE E QUATRO pontos abaixo de
# PLAY(55) e portanto muito fora do alcance de ~17 do prior. Pela hipotese
# registrada antes, ele deveria render ~zero. Rendeu o MESMO que o 0,75.
#
# **A explicacao "devolver autoridade ao prior" esta FALSIFICADA.** O que os
# dois valores tem em comum, e e a unica coisa que sobra, e a REORDENACAO:
# ATTACK e END passam a frente de CARD, TOOL, SKILL, COND, NUMBER, RETREAT,
# DISCARD, YES e NO. A unica diferenca entre eles e END ultrapassar CARD no
# 0,75 — e isso nao mudou o resultado.
#
#   O que paga e a ORDEM, nao a distancia.
#
# Coerente com o resto do que 18/08 mediu: o prior E a regra posicional dentro
# do tipo (docs/prior-contra-regra-trivial-2026-08-18.md), entao dar-lhe mais
# alcance nao podia ser a alavanca.
#
# ADOTADO S = 0,50 por PARCIMONIA: mesma medicao, reordenacao menor (mantem END
# abaixo de CARD). Entre duas mudancas indistinguiveis, a que mexe menos numa
# escala validada por dezenas de medicoes. A escolha e por parcimonia, NAO por
# evidencia — dentro da resolucao da bancada os dois sao o mesmo.
#
# As duas rodadas sao a REPLICACAO que o protocolo exige: +1,10 e +1,03 pp,
# sete centesimos de ponto entre duas medicoes de 44.000 partidas cada.
#
# YES e NO ficam em 12,0 de proposito: a divergencia deles e 0,0%.
# Para desligar: PTCG_COMPRESSAO_ATAQUE=0
COMPRESSAO_ATAQUE = float(os.environ.get("PTCG_COMPRESSAO_ATAQUE", "0.5"))

# A ancora e a CONSTANTE 50,0, nao `BASE_PRIORITY[OPT_ATTACH]`. Parece o mesmo e
# nao e: o `PRIO_ATTACH` do T7 torna o ATTACH ajustavel, e ler dele faria uma
# variante de T7 mover ATTACK e END junto — duas mudancas medidas como uma.
# 50,0 e o valor com que os +1,10 e +1,03 pp do T6 foram medidos; mudar a ancora
# mudaria o que "S=0,50" significa, em silencio.
_ANCORA_COMPRESSAO = 50.0

if COMPRESSAO_ATAQUE:
    for _tipo in (OPT_ATTACK, OPT_END):
        _v = BASE_PRIORITY[_tipo]
        BASE_PRIORITY[_tipo] = _v + (_ANCORA_COMPRESSAO - _v) * COMPRESSAO_ATAQUE


def select_indices(scores: list[float], min_count: int, max_count: int) -> list[int]:
    """Nucleo A PROVA DE INVARIANTES: retorna selecao sempre legal.

    Garante: sem duplicatas, cada indice em [0, len(scores)), len em [min_count, max_count]
    (clampado ao possivel). Selecao = maiores scores. Para min_count==0, so escolhe a melhor
    opcao se ela for benefica (score > 0); senao passa (lista vazia).
    """
    n = len(scores)
    max_count = max(0, min(int(max_count), n))
    min_count = max(0, min(int(min_count), max_count))
    order = sorted(range(n), key=lambda i: scores[i], reverse=True)
    if min_count >= 1:
        k = min_count
    else:
        k = 1 if (max_count >= 1 and n > 0 and scores[order[0]] > 0.0) else 0
    k = min(k, max_count)
    return sorted(order[:k])


def _opt_type(opt):
    """Tipo da opcao como INTEIRO, robusto a dict / objeto / enum.

    O engine entrega inteiros (0-15). O stub antigo supunha strings, e por isso
    o `score_options` caia sempre no fallback — ver docs/api-real.md.
    """
    t = opt.get("type") if isinstance(opt, dict) else getattr(opt, "type", None)
    if t is None:
        return None
    val = getattr(t, "value", t)  # IntEnum -> int
    try:
        return int(val)
    except (TypeError, ValueError):
        return None


def _opt_field(opt, nome, padrao=None):
    """Le um campo estruturado da opcao (area, index, attackId, ...)."""
    if isinstance(opt, dict):
        return opt.get(nome, padrao)
    return getattr(opt, nome, padrao)


def _opt_card_id(opt):
    """Card ID da opcao, quando ela o carrega.

    So os tipos 15 (`cardId`) trazem identidade de carta diretamente. Os demais
    apontam para uma POSICAO (`area` + `index`), e resolver isso em carta exige
    o State — ver `_resolve_card`, que depende de dados que a opcao sozinha nao
    tem. Por isso o bonus por dano fica indisponivel aqui.
    """
    v = _opt_field(opt, "cardId")
    return v if isinstance(v, int) else None


def score_options(options: list, obs_dict=None) -> list[float]:
    """Pontua cada opcao legal por prioridade heuristica.

    Trabalha sobre o esquema REAL das opcoes (inteiros + campos estruturados),
    nao sobre o stub. Ordem: atacar > evoluir > jogar carta > anexar energia >
    habilidade > selecionar carta > recuar > confirmar.

    Com `obs_dict`, aplica tambem a POLITICA POR CARTA — ver
    `_ajuste_por_carta`. Sem ele, o comportamento e exatamente o de antes: o
    parametro e opcional de proposito, porque metade dos chamadores (testes,
    arena antiga) so tem a lista de opcoes.
    """
    cur = _campo(obs_dict, "current") if obs_dict is not None else None
    sel = _campo(obs_dict, "select") if obs_dict is not None else None
    eu = int(_campo(cur, "yourIndex", 0) or 0) if cur is not None else 0

    scores = []
    for opt in options:
        t = _opt_type(opt)
        s = BASE_PRIORITY.get(t, OTHER_PRIORITY)

        if t == OPT_NUMBER:
            # Escolhas numericas (comprar N, colocar N contadores): mais e melhor.
            n = _opt_field(opt, "number", 0)
            s += float(n) if isinstance(n, (int, float)) else 0.0
        elif t == OPT_ATTACK:
            # Sem tabela attackId -> dano ainda; o id maior tende a ser o ataque
            # mais caro do Pokemon, que costuma bater mais. Desempate fraco e
            # declaradamente provisorio.
            aid = _opt_field(opt, "attackId")
            if isinstance(aid, int):
                s += min(aid, 999) * 0.001
        elif t in (OPT_ATTACH, OPT_EVOLVE):
            # Preferir agir sobre o ativo a mexer no banco. AreaType.ACTIVE = 4
            # (a versao anterior comparava com 0 e nunca disparava).
            area = _opt_field(opt, "inPlayArea")
            if isinstance(area, int):
                s += 3.0 if area == AREA_ACTIVE else 0.0
        elif t == OPT_ENERGY:
            cnt = _opt_field(opt, "count", 0)
            s += float(cnt) if isinstance(cnt, (int, float)) else 0.0

        if USAR_POLITICA_CARTA and cur is not None:
            s += _ajuste_por_carta(opt, cur, sel, eu)

        # UTILIDADE DE PEGAR — so na SELECAO MULTIPLA, que e exatamente onde o
        # `escolher_por_busca` desiste e nao ha busca nenhuma para corrigir a
        # ordem. Na selecao simples a busca roda e avalia o estado resultante,
        # que e melhor do que qualquer heuristica escrita a mao — por isso a
        # regra nao entra la.
        if (UTILIDADE_CARTA and cur is not None and t == OPT_CARD
                and sel is not None
                and (int(_campo(sel, "minCount", 1) or 1) != 1
                     or int(_campo(sel, "maxCount", 1) or 1) != 1)):
            cid = _carta_da_opcao(opt, cur, sel, eu)
            if cid is not None:
                s += _utilidade_de_pegar(cid, cur, eu)

        # Desempate estavel por posicao: evita que opcoes do mesmo tipo fiquem
        # empatadas e caiam sempre no indice 0.
        idx = _opt_field(opt, "index")
        if isinstance(idx, int):
            s += idx * 1e-3

        scores.append(float(s))
    return scores


# ---------------------------------------------------------------------------
# POLITICA POR CARTA
#
# O que existia ate aqui: o agente pontuava por TIPO de opcao. Toda carta
# jogada da mao valia 55,0, fosse ela o Lillie's Determination ou o Briar. As
# unicas coisas especificas de carta no codigo eram as tabelas de dano, os
# premios e o efeito de HP/cura.
#
# A auditoria de 12/08 mostrou que ONZE das quinze cartas do deck nao tinham
# criterio nenhum. E mostrou tambem que o agente JOGA as cartas — 78% a 96% dos
# turnos em que elas aparecem. O problema nunca foi "ele nao joga"; e "ele nao
# escolhe a hora, nem entre quais".
#
# Isso fica claro nos Apoiadores: Judge, Boss's Orders, N's Plan e Briar param
# todos em ~55% por turno. Nao e desprezo — **so se joga UM Apoiador por
# turno**, e o Lillie's ganha a disputa com 81%. A pergunta certa nao e se o
# agente joga a carta, e sim qual das quatro ele escolhe.
#
# As regras abaixo respondem isso. Cada uma sai de uma conta ou de uma medicao,
# nunca de gosto, e o valor entra na MESMA escala do BASE_PRIORITY (dezenas).
# ---------------------------------------------------------------------------

# Aceita "1"/"all" para tudo, ou uma lista: "judge,boss". Cada regra tem que
# poder ser medida SOZINHA — um pacote de oito regras que passa no painel nao
# diz quais delas pagaram, e provavelmente algumas atrapalham.
_POLITICA_ENV = os.environ.get("PTCG_POLITICA_CARTA", "0").strip().lower()
USAR_POLITICA_CARTA = _POLITICA_ENV not in ("", "0", "none")
REGRAS_LIGADAS = (None if _POLITICA_ENV in ("1", "all", "todas")
                  else {r.strip() for r in _POLITICA_ENV.split(",") if r.strip()})

# Quanto uma regra empurra ou segura uma carta. Escolhidos por ORDEM DE
# GRANDEZA sobre o BASE_PRIORITY, nao varridos: OPT_PLAY vale 55 e OPT_ATTACH
# 50, entao 8 reordena dentro da faixa e 30 atravessa faixas.
P_FORTE = 30.0
P_MEDIO = 8.0


def _mao_dos_dois(cur, eu) -> tuple[int, int]:
    """(cartas na nossa mao, cartas na mao dele)."""
    jog = _campo(cur, "players") or []
    if len(jog) < 2:
        return 0, 0
    meu, dele = jog[eu] or {}, jog[1 - eu] or {}
    minha = _campo(meu, "hand")
    n_minha = len(minha) if isinstance(minha, list) else int(
        _campo(meu, "handCount", 0) or 0)
    return n_minha, int(_campo(dele, "handCount", 0) or 0)


def _ajuste_por_carta(op, cur, sel, eu) -> float:
    """Ajuste de nota para a carta desta opcao. 0 quando nao ha regra."""
    t = _opt_type(op)
    if t not in (OPT_PLAY, OPT_CARD, OPT_TOOL_CARD):
        return 0.0

    # Selecao ABERTA por uma carta: o engine diz qual em `select.effect`. E aqui
    # que se escolhe o alvo do Boss's Orders — nao na hora de joga-lo.
    efeito = _campo(sel, "effect")
    if efeito is not None and _campo(efeito, "id") == CARD_BOSS:
        if REGRAS_LIGADAS is None or "boss" in REGRAS_LIGADAS:
            try:
                return float(_escolha_de_alvo_do_boss(op, cur, sel, eu))
            except Exception:
                return 0.0
        return 0.0

    cid = _carta_da_opcao(op, cur, sel, eu)
    if cid is None:
        return 0.0
    par = _REGRAS_CARTA.get(cid)
    if par is None:
        return 0.0
    nome, regra = par
    if REGRAS_LIGADAS is not None and nome not in REGRAS_LIGADAS:
        return 0.0
    try:
        return float(regra(op, cur, sel, eu))
    except Exception:
        return 0.0


# --------------------------------------------------------------- as regras

def _regra_judge(op, cur, sel, eu) -> float:
    """Judge: os dois embaralham a mao e compram 4.

    A conta e simetrica e por isso e facil de errar: jogar o Judge troca a
    NOSSA mao por 4 e a DELE por 4. O saldo e `mao dele - nossa mao`.

    Medido, no momento em que o Judge e oferecido: a mao dele tem 2,9 cartas em
    media e a nossa 5,8. Ou seja, na media o Judge REPOE a mao do adversario e
    ENCOLHE a nossa — perde dos dois lados. O agente o joga em 56% dos turnos.

    A regra do Fernando, mais restritiva que o saldo puro e por isso mais
    segura: so vale com a nossa mao vazia (compramos de graca) ou com a dele
    cheia (a disrupcao paga).
    """
    minha, dele = _mao_dos_dois(cur, eu)
    if minha <= 1 or dele >= 6:
        return P_FORTE
    return -P_FORTE


def _regra_lillies(op, cur, sel, eu) -> float:
    """Lillie's Determination: embaralha a mao e compra 6 (8 com 6 premios).

    So depende da NOSSA mao — nao devolve nada ao adversario. Com a mao
    pequena e compra grande; com a mao grande, joga cartas fora.
    """
    minha, _ = _mao_dos_dois(cur, eu)
    return P_MEDIO if minha <= 5 else -P_MEDIO


CARD_BOSS = 1182


def _escolha_de_alvo_do_boss(op, cur, sel, eu) -> float:
    """Qual Pokemon do banco DELE arrastar para o ativo.

    BUG CORRIGIDO em 2026-08-12: a primeira versao desta regra olhava
    `inPlayIndex` na opcao de JOGAR o Boss's Orders. Nao existe alvo ali — a
    carta e jogada, e so ENTAO o engine abre uma selecao perguntando qual
    Pokemon do banco. Medido: a regra disparou ZERO vezes em 3.893 decisoes.

    O contexto certo vem de `select.effect`, que o engine preenche com a carta
    que esta ativando o efeito.

    REESCRITA em 14/08, a partir da ideia do Fernando: "colocar na frente o
    Pokemon que e a maior ameaca para tomar dano primeiro".

    A ideia esta certa, e por um motivo mais especifico do que ele deu. O
    Myriad Leaf Shower soma 30 por energia nos DOIS ativos, entao a energia do
    ALVO e um multiplicador do NOSSO dano:

        4 energias minhas, alvo com 0 energia  ->  150
        4 energias minhas, alvo com 4 energias ->  270

    Isso inverte o dilema normal do Boss's Orders. No TCG generico se arrasta o
    alvo fraco do banco para roubar um premio barato; aqui a ameaca carregada e
    ao mesmo tempo a mais perigosa E a mais facil de matar, porque ela alimenta
    o nosso ataque.

    Mas a ideia nao sobrevive inteira. Medido contra o campo real: os Mega de
    300-340 PS exigem 5 a 7 energias minhas mesmo carregados, fora do alcance.
    Arrastar o Mega Lucario sem poder mata-lo e ENTREGAR a ele a posicao de
    ataque.

    O criterio certo nao e "a maior ameaca" nem "o menor PS". E:

        consigo mata-lo NESTE turno?

    e, entre os que consigo, o de maior premio. A versao anterior desta regra
    errava nos dois sentidos: so penalizava PERDER energia (nunca premiava
    ganhar) e nunca checava se o nocaute acontece.

    Por que regra e nao classificador: aqui todas as opcoes da selecao sao do
    MESMO tipo, entao a prioridade base e identica e nao ha o problema de
    autoridade que trava o recuo. O que falta e INFORMACAO — nenhuma das 50
    features carrega a energia do alvo. So que, acrescentada a informacao, a
    decisao vira aritmetica de tres termos, e um classificador teria que
    aprender de poucas dezenas de exemplos (sao 2 copias em 60 cartas) uma
    formula que sabemos escrever.
    """
    jog = _campo(cur, "players") or []
    if len(jog) < 2:
        return 0.0
    dele, meu = jog[1 - eu] or {}, jog[eu] or {}
    ativo = _primeiro(_campo(dele, "active"))
    meu_ativo = _primeiro(_campo(meu, "active"))
    if ativo is None or meu_ativo is None:
        return 0.0
    alvo_id = _carta_da_opcao(op, cur, sel, eu)
    banco = [pk for pk in (_campo(dele, "bench") or []) if pk is not None]
    alvo = next((pk for pk in banco if _campo(pk, "id") == alvo_id), None)
    if alvo is None:
        return 0.0

    dano = _meu_dano_contra(meu_ativo, alvo, cur)
    if dano is None:
        return 0.0

    mata = dano >= _hp_efetivo(alvo)
    if not mata:
        # Nao matar e o caso ruim, e ele piora com o tamanho da ameaca: puxar o
        # Mega Lucario sem poder derruba-lo e ENTREGAR a ele a posicao de
        # ataque. Compara com quem ja esta na frente.
        ameaca_alvo = _ameaca({"active": [alvo]}, meu_ativo, cur, com_fraqueza=True)
        ameaca_atual = _ameaca({"active": [ativo]}, meu_ativo, cur, com_fraqueza=True)
        return -P_FORTE if ameaca_alvo > ameaca_atual else -P_MEDIO

    # Mata. Entre os que morrem, o de maior premio primeiro; e desempata pela
    # ameaca que sai do caminho.
    nota = P_MEDIO * _premios_que_vale(alvo)
    if not _pode_matar(meu_ativo, ativo, cur):
        # o ativo dele NAO morre neste turno: arrastar troca um alvo vivo por um
        # morto, que e o melhor uso possivel da carta
        nota += P_MEDIO
    return min(nota, P_FORTE)


def _meu_dano_contra(meu_ativo, alvo, cur) -> float | None:
    """Dano do nosso melhor ataque contra `alvo`, com a escala dos dois ativos.

    None quando nao da para saber — sem tabela de ataque, ou o ativo nao tem
    ataque conhecido. Nesses casos a regra se cala em vez de chutar.
    """
    if not _ATAQUE_DANO:
        return None
    minha_e = _conta_energia(meu_ativo)
    alvo_e = _conta_energia(alvo)
    meu_id, alvo_id = _campo(meu_ativo, "id"), _campo(alvo, "id")
    reducao = _reducao_do_defensor(alvo, cur)

    melhor = None
    for atk_id, base in _ATAQUE_DANO.items():
        if not _ataque_do_pokemon(meu_id, atk_id):
            continue
        bruto = base + _ESCALA_DOIS_ATIVOS.get(atk_id, 0) * (minha_e + alvo_e)
        efetivo = _dano_efetivo(bruto, meu_id, alvo_id, reducao)
        melhor = efetivo if melhor is None else max(melhor, efetivo)
    return melhor


def _pode_matar(meu_ativo, defensor, cur) -> bool:
    d = _meu_dano_contra(meu_ativo, defensor, cur)
    return d is not None and d >= _hp_efetivo(defensor)


def _regra_tool_scrapper(op, cur, sel, eu) -> float:
    """Tool Scrapper: descarta ate 2 Ferramentas, de qualquer lado.

    Decisao do Fernando: tirar a PRIMEIRA ferramenta que aparecer no
    adversario. Sem ferramenta dele em campo, a carta nao faz nada — e o
    engine ainda assim a oferece.
    """
    jog = _campo(cur, "players") or []
    if len(jog) < 2:
        return 0.0
    dele = jog[1 - eu] or {}
    com_ferramenta = sum(
        1 for pk in list(_campo(dele, "active") or []) + list(_campo(dele, "bench") or [])
        if pk is not None and (_campo(pk, "tools") or []))
    return P_MEDIO if com_ferramenta else -P_FORTE


def _regra_ns_plan(op, cur, sel, eu) -> float:
    """N's Plan: move ate 2 Energias do banco para o ativo.

    O combo do deck: o Ogerpon do banco se carrega sozinho (Teal Dance anexa a
    SI MESMO) e e imune a ataque enquanto la (Tera). O N's Plan traz essa
    energia para a frente na hora do golpe.

    So vale se ha energia no banco para mover.
    """
    jog = _campo(cur, "players") or []
    if len(jog) < 2:
        return 0.0
    meu = jog[eu] or {}
    no_banco = sum(_conta_energia(pk) for pk in (_campo(meu, "bench") or [])
                   if pk is not None)
    if not no_banco:
        return -P_FORTE
    ativo = _primeiro(_campo(meu, "active"))
    # mais valioso quando o ativo ainda nao tem com que atacar
    return P_FORTE if _conta_energia(ativo) < 3 else P_MEDIO


def _regra_briar(op, cur, sel, eu) -> float:
    """Briar: com o adversario em exatamente 2 premios, um nocaute do nosso
    Pokemon Tera rende 1 premio a mais — ou seja, FECHA a partida.

    Medido em 14/08: uso de 43%, o menor do deck, e jogada quando ainda faltam
    3,7 premios em media. Ela e carta de FECHAMENTO e estava sendo gasta cedo.

    A regra precisa enxergar a oportunidade, nao so a condicao:

      ele em 2 premios E o nosso ataque MATA o ativo dele  -> fecha a partida
      ele em 2 premios, mas o ataque nao mata              -> guarda
      qualquer outro caso                                  -> nao joga

    Sem o nocaute no mesmo turno a Briar nao faz nada: o premio extra so vem
    se houver nocaute, e ela dura um turno so.
    """
    jog = _campo(cur, "players") or []
    if len(jog) < 2:
        return 0.0
    meu, dele = jog[eu] or {}, jog[1 - eu] or {}
    premios_dele = len(_campo(dele, "prize") or [])
    if premios_dele != 2:
        return -P_FORTE          # fora da condicao, e carta morta

    ativo = _primeiro(_campo(meu, "active"))
    alvo = _primeiro(_campo(dele, "active"))
    if ativo is None or alvo is None:
        return 0.0

    # o nosso ataque mata o ativo dele NESTE turno?
    hp = _hp_efetivo(alvo)
    reducao = _reducao_do_defensor(alvo, cur)
    meu_id, alvo_id = _campo(ativo, "id"), _campo(alvo, "id")
    for o in (_campo(sel, "option") or []):
        if _opt_type(o) != OPT_ATTACK:
            continue
        base = _ATAQUE_DANO.get(_opt_field(o, "attackId"))
        if base is None:
            continue
        if _dano_efetivo(base, meu_id, alvo_id, reducao) >= hp:
            return P_FORTE       # fecha a partida
    return -P_MEDIO              # a condicao vale, mas nao fecha: guarda


# Estadios do meta que ATRAPALHAM o nosso Ogerpon, medidos em 14/08. Jogar um
# estadio REMOVE o que estava em campo, entao anular custa zero alem da carta.
#
#   Nighttime Mine (Alakazam, 14,8% do campo)
#     "Attacks used by each Tera Pokemon in play cost {C} more" — o nosso
#     Ogerpon E Tera, entao o Myriad Leaf Shower passa de 3 para 4 energias.
#     E o unico estadio do campo que nos ataca diretamente.
#   Lively Stadium (espelho, 5,6%)
#     +30 PS em todo Basico. Ajuda os dois, mas o espelho tem o mesmo HP —
#     e neutro, nao vale a carta para remover.
_ESTADIOS_CONTRA_NOS = {1266}   # Nighttime Mine


def _regra_estadio(op, cur, sel, eu) -> float:
    """Quando jogar o estadio: cedo, ou segurar para anular o dele?

    Medido em 14/08: **85,3% do campo joga estadio**. Jogar cedo entrega o
    campo de graca — ele poe o dele por cima e o nosso vira carta perdida.

    A regra:
      campo vazio           vale, mas fraco: ele provavelmente vai substituir
      estadio DELE que nos  atrapalha -> ANULAR e prioridade
      estadio dele neutro   vale, mas nao e urgente
      estadio IGUAL ao nosso  desperdicio puro
    """
    em_jogo = _primeiro(_campo(cur, "stadium"))
    cid = _carta_da_opcao(op, cur, sel, eu)
    if em_jogo is None:
        # Campo vazio. Com 85% do campo jogando estadio, o nosso tende a ser
        # substituido — segurar tem valor de opcao. Mas o Gravity Mountain
        # tira 30 PS dos Estagio 2 dele, e o meta e 66% Estagio 2, entao
        # tambem ha ganho em estar em campo. Positivo fraco.
        return P_MEDIO / 2
    id_em_jogo = _campo(em_jogo, "id")
    if id_em_jogo == cid:
        return -P_FORTE          # trocar por um igual nao faz nada
    if id_em_jogo in _ESTADIOS_CONTRA_NOS:
        return P_FORTE           # anular o que nos atrapalha
    return P_MEDIO


# cardId -> regra. Cravar id aqui e deliberado e diferente do erro do ref950:
# estas sao regras de USO de carta especifica, nao uma tabela de dano que
# deveria ser geral. Uma carta que sai do deck simplesmente perde a regra.
CARD_JUMBO = 1147
CURA_JUMBO = 80.0


def _regra_cura(op, cur, sel, eu) -> float:
    """Jumbo Ice Cream: cura 80 do ativo com 3 ou mais energias.

    A observacao do Fernando em 14/08, e ela estava certa: eu media a ENERGIA
    no momento do uso (5,5 em media) e reportava como se fosse bom. Energia e
    so o PRE-REQUISITO. A politica tem que ser sobre DANO.

    Medido em 89 usos:
      dano medio no ativo ao usar     95
      DESPERDICIO (dano < 20)         10%  — cura 80 e devolve menos de 20
      morre no proximo turno mesmo    58%  — a cura nao muda o desfecho
      cura util                       21%

    Ou seja, **68% dos usos nao mudam nada**. A regra abaixo e a mesma logica
    do `proteger_do_nocaute`, aplicada como ajuste de nota em vez de override:
    so vale quando a cura MUDA o desfecho.
    """
    jog = _campo(cur, "players") or []
    if len(jog) < 2:
        return 0.0
    meu, dele = jog[eu] or {}, jog[1 - eu] or {}
    ativo = _primeiro(_campo(meu, "active"))
    if ativo is None:
        return 0.0

    maximo = float(_campo(ativo, "maxHp", 0) or 0)
    hp = _hp_efetivo(ativo)
    dano = max(0.0, maximo - hp)
    if dano < 20:
        return -P_FORTE          # cura menos de 20: desperdicio puro

    curado = min(CURA_JUMBO, dano)
    ameaca = _ameaca(dele, ativo, cur, com_fraqueza=True)
    if not ameaca:
        # ninguem nos ameaca: curar agora nao urge, mas nao e erro
        return 0.0
    if ameaca >= hp + curado:
        return -P_FORTE          # morre no proximo turno mesmo com a cura
    if ameaca >= hp:
        return P_FORTE           # morreria sem a cura, sobrevive com ela
    return 0.0                   # sobreviveria de qualquer jeito


# ---------------------------------------------------------------------------
# UTILIDADE DE PEGAR UMA CARTA — a fatia que a busca nunca ve
#
# Medido em 4.000 decisoes reais da ladder (tools/decisoes_sem_busca.py):
# **16,6%** [15,5; 17,8] das decisoes sao de SELECAO MULTIPLA, e nelas o
# `escolher_por_busca` devolve None na segunda linha — "o leque de combinacoes
# nao cabe em 1 ply". **98% delas sao do tipo CARD**: "olhe N cartas e pegue k".
# Sao o Bug Catching Set, o Pokegear 3.0, o Lillie's e o Tera Orb — 16 das 60
# cartas da lista.
#
# E e exatamente a regiao em que o projeto ja mediu que o modelo aprendido nao
# vale nada: 47,7% de acerto em CARD, que EMPATA com "pegue a primeira da
# lista"; entre Apoiadores, 32,0%, e a regra trivial GANHA. A feature `indice`
# pesa 9,4x a segunda. Somando: a busca nao roda, e a avaliacao que sobra e
# posicional.
#
# A regra abaixo poe uma preferencia derivada do PLANO DO DECK no lugar da
# posicao. Ela nao e varrida: a ordem sai do que a lista precisa para funcionar,
# e cada degrau tem um motivo mecanico.
#
#   1. Ogerpon      — e o UNICO atacante. Sem ele nao ha plano.
#   2. energia {G}  — o Teal Dance exige energia NA MAO; sem ela a habilidade
#                     nao e sequer oferecida, e ela e o motor do deck.
#   3. Tera Orb     — busca deterministica do Ogerpon: um Ogerpon adiado.
#   4. Apoiador     — vale menos se JA se jogou apoiador neste turno (so um por
#                     turno), e ai a carta fica parada.
#
# Os degraus ficam na escala do BASE_PRIORITY (dezenas) e sao espacados o
# suficiente para nao dependerem de ajuste fino.
UTILIDADE_CARTA = os.environ.get("PTCG_UTILIDADE_CARTA", "0") not in ("", "0")

_OGERPON = 96
_ENERGIA_G = (1, 18)          # Basic {G} e Grow Grass
_TERA_ORB = 1127
_APOIADORES = (1227, 1182, 1201, 1213, 1221)   # Lillie's, Boss, Briar, Judge, N's


def _utilidade_de_pegar(cid, cur, eu) -> float:
    """Quanto vale PEGAR esta carta agora. Zero quando nao ha razao."""
    jog = _campo(cur, "players") or []
    meu = jog[eu] if eu < len(jog) else None

    if cid == _OGERPON:
        em_jogo = 1 if _primeiro(_campo(meu, "active")) is not None else 0
        em_jogo += len(_campo(meu, "bench") or [])
        # com o campo vazio o Ogerpon e a partida; com campo montado, ainda e a
        # melhor carta, mas deixa de ser urgente
        return 40.0 if em_jogo < 2 else 20.0

    if cid in _ENERGIA_G:
        mao = _campo(meu, "hand") or []
        na_mao = sum(1 for c in mao
                     if _campo(c, "id") in _ENERGIA_G)
        # 2 anexos por turno (o normal + o Teal Dance): abaixo disso, energia na
        # mao e o gargalo do turno seguinte
        return 30.0 if na_mao < 2 else 10.0

    if cid == _TERA_ORB:
        return 18.0

    if cid in _APOIADORES:
        # so se joga UM apoiador por turno; se ja foi, a carta dorme
        return 4.0 if _campo(cur, "supporterPlayed") else 14.0

    return 0.0


_REGRAS_CARTA = {
    1213: ("judge", _regra_judge),
    1227: ("lillies", _regra_lillies),
    1137: ("scrapper", _regra_tool_scrapper),
    CARD_JUMBO: ("cura", _regra_cura),
    1221: ("ns_plan", _regra_ns_plan),
    1201: ("briar", _regra_briar),
    1251: ("estadio", _regra_estadio),   # Lively Stadium
    1252: ("estadio", _regra_estadio),   # Gravity Mountain
}
NOMES_REGRAS = sorted({n for n, _ in _REGRAS_CARTA.values()} | {"boss"})


def _lead_int(dmg) -> int:
    if not isinstance(dmg, str):
        return 0
    i = 0
    for ch in dmg.strip():
        if ch.isdigit():
            i = i * 10 + int(ch)
        else:
            break
    return i


# ---------------------------------------------------------------------------
# L1 — busca de 1 ply com o forward model sancionado.
# Ver docs/plano-L1.md. A L0 pontua a OPCAO; o L1 pontua o ESTADO que ela
# produz. Custo medido: search_begin 0,8 ms + 0,11 ms por opcao, contra ~4,3 s
# de orcamento por decisao.
# ---------------------------------------------------------------------------
USAR_L1 = True  # passou no gate: 54,1% [52,2; 56,1] em N=2.500 (docs/experimentos.md § L1c)

# Pesos por ordem de grandeza, nao por tuning: tunar antes de saber se o L1
# ganha e otimizar ruido.
W_PREMIO = 1000.0   # condicao de vitoria
W_KO = 300.0        # nocaute vira premio
# W_DANO — progresso no ativo dele. NAO MEXA SEM LER ISTO.
#
# Este termo sempre valeu ZERO. Ele lia `_campo(ativo_dele, "damage", 0)`, e o
# Pokemon em jogo nao tem campo `damage`: conferido em 2.258 Pokemon observados
# em partida, nenhum o trazia — enquanto 429 estavam feridos. O dado existe, e
# `maxHp - hp`.
#
# Parece bug de uma linha. Nao e: liga-lo PIORA, medido nas duas formas.
#
#   variante       o que faz                            painel
#   dano_real      (maxHp-hp) x W_DANO=2,0             -11,46pp [-17,28; -5,63]
#   dano_fracao    (dano/maxHp) x W_KO, limitado a 1    -7,37pp [-10,02; -4,73]
#
# A forma absoluta viola a ordem da propria avaliacao: um ativo com 190 de dano
# marcado vale 380 e derruba-lo vale W_KO=300, entao a avaliacao paga mais por
# deixar o adversario quase morto. A forma em fracao corrige isso e ainda
# assim perde 7pp, o que aponta para a causa mais antiga do projeto: premiar
# dano empurra o agente a ATACAR CEDO, e atacar encerra o turno. Foi a mesma
# medicao que ja tinha custado 57,6pp quando ATTACK estava no topo da L0.
#
# Fica em 2,0 multiplicando zero, de proposito, com os dois caminhos atras de
# flag em `_dano_acumulado` / `_fracao_derrubada`. Reviver este termo e uma
# armadilha ja paga duas vezes.
W_DANO = 2.0
# Ajustavel so para a REPLICA do T13: a forma 1 com o peso pela metade
# responde se o que corrige e remover o bonus de rotacao (e ai o peso e
# secundario) ou o peso em si. Padrao 1,0 — o valor de sempre.
W_HP = float(os.environ.get("PTCG_W_HP", "1.0"))   # sobrevivencia

# O TERMO DE VIDA PAGA POR TROCAR DE POKEMON, e isso foi medido em 24/08.
#
# `s += _hp_efetivo(meu_ativo) * W_HP` conta a vida do ATIVO e mais nada. Recuar
# um Ogerpon machucado e promover um inteiro nao cura ninguem — mas a avaliacao
# ve a vida do ativo saltar de 60 para 210 e paga **+150**. Descontando as
# energias que ficam para tras (5 x 15), o saldo ainda e **+75**: cinco energias
# anexadas, de graca, sem causar dano nenhum.
#
# E atacar, na mesma avaliacao, vale ZERO a menos que nocauteie: o W_DANO esta
# em 0 de proposito, porque premiar dano parcial mediu -11,46 e -7,37 pp.
#
# O resultado, medido nas MESMAS posicoes de pilotos >= 1.000 do nosso
# arquetipo (tools/divergencia_do_agente.py):
#
#     tipo       eles     nos    razao
#     ATTACK    12,1%    4,8%    0,39x   <- atacamos 2,5x MENOS
#     RETREAT    3,7%   11,6%    3,18x   <- recuamos 3,2x MAIS
#
# O agente faz exatamente o que o objetivo manda: gira Pokemon para manter vida
# alta no ativo, em vez de atacar.
#
# A CORRECAO, quando ligada: em vez de premiar a vida do ativo, PENALIZA o dano
# acumulado em todo o campo. Dano nao se move com o recuo — trocar de ativo nao
# cura —, entao o termo passa a ser invariante a rotacao. E nao cria a distorcao
# oposta: um Pokemon novo no banco contribui zero, e nao 210, entao encher o
# banco nao vira recompensa.
# 1 = penaliza o dano do campo; 2 = premia a vida do campo. As duas sao
# invariantes ao recuo, e divergem em `Sum(maxHp)`: a forma 2 paga 210 por
# Pokemon novo no banco, contra os 8 do W_BANCO. A 2 e a REPLICA da 1.
# ADOTADO em 25/08 com a forma 1. Tres medicoes: +0,86 (10 rep), +0,65
# (10 rep, peso 0,5) e +0,59 [+0,09; +1,09] com 20 replicas, gate passando
# e nenhuma casa regredindo. O numero a citar e o de MAIOR N: +0,59.
# A forma 2 (vida do campo) foi medida e NAO ganha — a invariancia ao
# recuo e necessaria, e nao suficiente.
HP_INVARIANTE = int(os.environ.get("PTCG_HP_INVARIANTE", "1") or 0)

# O QUE A AVALIACAO NAO ENXERGA DO OUTRO LADO DA MESA.
#
# Auditoria de 25/08 (tools/auditoria_de_entradas.py + quanto_pesa_o_buraco.py):
# o `avaliar_estado` le o NOSSO banco e a NOSSA energia, e do adversario le so o
# ativo — para dano acumulado e ameaca. O banco dele e invisivel, e a energia
# dele so entra pelo `_ameaca`.
#
# Medido em 5.806 decisoes nossas:
#
#     banco dele NAO vazio          93,6%   (media de 3,41 Pokemon)
#     ativo dele com energia        66,1%   (media de 1,11)
#     nosso banco cheio              0,0%   <- benchMax nao importa
#     condicoes especiais            0,0%   <- veneno/queimadura nao acontecem
#
# DUAS HIPOTESES, e as duas com peso DERIVADO, nao escolhido:
#
# A) energia no ativo DELE conta a FAVOR. Nao e intuitivo e e mecanica pura: o
#    Myriad Leaf Shower soma 30 por energia anexada aos DOIS ativos, entao a
#    energia dele multiplica o NOSSO dano. E o mesmo argumento que fez o projeto
#    rejeitar o Crushing Hammer — tirar energia do alvo custa 14% do nosso dano.
#    Peso: o MESMO W_ENERGIA da nossa, porque a contribuicao de dano e identica.
#
# B) o banco dele conta CONTRA, espelhando o nosso. Peso: o mesmo W_BANCO.
# A) REPROVADA POR CONSTRUCAO em 25/08, antes do painel. A avaliacao julga o
#    estado do FIM DO TURNO, depois do nosso ataque. Se o ataque nocauteia, o
#    ativo dele vira um com ZERO energia — entao este termo DESESTIMULA matar
#    o alvo, porque matar apaga a energia que ele premiava.
#    O que e verdade e "atacar um alvo carregado causa mais dano", e isso e
#    propriedade da ACAO, nao do ESTADO. Fica no codigo, desligada, porque a
#    razao da morte vale mais que o teste: e a mesma confusao que fez premiar
#    dano custar -11,46 e -7,37 pp.
ENERGIA_DO_ALVO = os.environ.get("PTCG_ENERGIA_DO_ALVO", "0") == "1"
BANCO_DELE = os.environ.get("PTCG_BANCO_DELE", "0") == "1"

# T16 — a energia DELE conta CONTRA nos. E o SINAL INVERTIDO do ENERGIA_DO_ALVO
# acima, e a inversao e a hipotese inteira.
#
# O T14a somava a energia do ativo dele (mecanica: o Myriad Leaf Shower conta a
# energia dos DOIS ativos, entao a dele multiplica o nosso dano). Morreu por
# construcao: a avaliacao pontua o estado do FIM DO TURNO, entao premiar a
# energia dele DESESTIMULA nocautear — matar apaga o que o termo premiava.
#
# Aqui e o contrario, e vem do Fernando: nocautear um alvo carregado TIRA
# RECURSO do adversario, e isso deveria valer.
#
#     alvo dele com 3 energias vivo    ->  -45
#     nocauteado, ele promove com 0    ->    0
#
# O termo passa a PREMIAR matar quem esta carregado, em vez de desestimular.
#
# O que ele NAO conserta, e isso ja esta medido: o agente nao perde nocautes.
# Em 917 chances ele chegou em 916 (99,9%), e fechou 552 de 553 vitorias. O
# nocaute ja vale W_PREMIO = 1000 pela contagem de premios, e ex ja vale 2000
# porque ex da 2 premios. Se este termo mudar alguma coisa, sera na ESCOLHA DE
# ALVO e no timing, nao em achar o nocaute.
ENERGIA_DELE_CONTRA = os.environ.get("PTCG_ENERGIA_DELE_CONTRA", "0") == "1"
W_BANCO = 8.0       # desenvolvimento
# W_MAO foi REMOVIDO: premiar cartas na mao faz o agente NAO jogar.
# Medido: com peso 3.0 em handCount, o L1 escolheu END em 275 de 359 decisoes
# (a L0, nenhuma) — jogar uma carta custava -3 e o ganho de campo nem sempre
# aparecia no mesmo ply. Carta na mao nao e valor; valor e o que esta em campo.

# Energia anexada ao ativo. EM TESTE, desligada por padrao.
# Motivo: medido em 120 partidas com o deck do Ogerpon, o agente usa o Teal
# Dance em 28,5% das ofertas e termina com 3,59 energias no ativo — o ataque
# precisa de 3 so para sair e escala 30 por energia. A avaliacao nao enxerga
# energia, entao anexar nao "vale" nada e a busca prefere qualquer outra coisa.
# Diferente do W_MAO: energia anexada esta EM CAMPO, nao na mao, e converte em
# dano. Mesmo assim entra medida, nao por argumento.
W_ENERGIA = float(os.environ.get("PTCG_W_ENERGIA", "15.0"))

# ONDE a energia esta vale o mesmo? Ate 21/08 valia — e isso tem consequencia
# medida.
#
# O `avaliar_estado` somava energia do ativo E do banco com o MESMO peso, com o
# comentario "o banco tambem e investimento". Mas o Myriad Leaf Shower conta a
# energia dos DOIS ATIVOS: energia no banco da **zero** de dano neste turno.
#
# E o Teal Dance anexa a energia A SI MESMO. Entao usar a habilidade do Ogerpon
# do banco poe a energia do turno em quem nao vai atacar — e, para a avaliacao,
# os dois estados ficavam com a MESMA nota. Empate na nota, e o desempate cai no
# indice da opcao.
#
# Medido em 400 partidas (tools/auditoria_de_turno.py, 2.521 turnos nossos):
# entre os turnos com mais de uma habilidade oferecida e o ativo entre elas,
# **23,7% comecam pelo banco**.
#
# O peso do banco entra como FRACAO do peso do ativo, e os valores sao
# PRE-DEFINIDOS, nao varridos: 0,5 (metade) e 0,0 (nada). Varrer e escolher o
# melhor depois seria o jardim de caminhos que se bifurcam.
# ADOTADO em 23/08 com 0.0. Painel +0,80 pp; replica com o instrumento certo
# (comparar_decks, replicas alternadas, Welch) +0,88 pp IC [+0,33; +1,43],
# gate conjuntivo passando e 9 de 10 replicas pareadas (p=0,021). O ganho
# esta nas duas casas de Lucario (+1,15 e +1,59 pp) e nenhuma casa regride.
# NAO esta estabelecido que 0,0 seja melhor que 0,5: o painel os separa por
# 0,23 pp. O 0,0 e o que foi medido com o instrumento certo.
FRACAO_ENERGIA_BANCO = float(
    os.environ.get("PTCG_FRACAO_ENERGIA_BANCO", "0.0"))

# AMEACA — o "dano previsto", no roadmap desde 08/08 e nunca construido.
#
# O agente e cego para sobrevivencia. Ja tentamos resolver SIMULANDO o turno do
# adversario (2 ply) e piorou 4,9pp, porque o turno dele e conduzido pela nossa
# L0, que joga mal. O agente publico de LB ~950 resolve sem simular: olha o
# campo dele, supoe uma energia a mais, consulta uma tabela de dano e penaliza
# o estado onde o nosso ativo morre.
#
# A tabela dele tem SEIS cartas cravadas e `energias * 40` para o resto. A
# nossa tem 1.004, geradas do CSV oficial, com o teto do bonus condicional.
# LIGADOS por padrao. Passaram no painel de 4 oponentes, 30.000 partidas por
# variante, positivo nas QUATRO casas e sem regressao em nenhuma:
#
#   casa                  rollout   ameaca+energia      dif        p
#   ref950+Lucario 0,05s    16,4%            17,1%   +0,70pp   0,251
#   ref950+Lucario 0,5s     16,3%            17,4%   +1,10pp   0,072
#   ref950+sample           53,9%            56,6%   +2,70pp   0,0009
#   primeira (piso)         58,0%            58,5%   +0,51pp   0,529
#   AGREGADO                36,1%            37,4%   +1,25pp   0,0015
#                           IC [+0,48; +2,02]
#
# Ressalva registrada: o grosso vem da casa `ref950+sample`, que e justamente
# aquela em que o oponente esta desencaixado do proprio deck. Nas duas casas
# duras o ganho e +0,70 e +1,10pp, nenhum significativo sozinho. A leitura
# conservadora e que o efeito e real e da ordem de +1pp.
#
# Os dois termos SO funcionam juntos: ameaca sozinha deu +0,16pp e energia
# sozinha (varrida em 0/5/15/40) nao mexeu nada. Faz sentido — saber que vai
# morrer so muda a jogada se o agente tambem valorizar o que perde ao morrer.
# Pesos por ordem de grandeza dos que ja existiam, nunca tunados.
W_AMEACA = float(os.environ.get("PTCG_W_AMEACA", "2.0"))    # dano previsto
W_LETAL = float(os.environ.get("PTCG_W_LETAL", "1000"))     # por premio em risco
W_DECKOUT = float(os.environ.get("PTCG_W_DECKOUT", "50"))   # deck acabando


def _campo(obj, nome, padrao=None):
    """Le um campo de dict OU de dataclass — o engine devolve os dois formatos.

    `obs_dict` chega como dict cru; o `SearchState` do forward model devolve
    dataclasses tipadas. A avaliacao roda sobre os dois.
    """
    if obj is None:
        return padrao
    if isinstance(obj, dict):
        return obj.get(nome, padrao)
    return getattr(obj, nome, padrao)


def _hp_efetivo(pk) -> float:
    """HP restante. `hp` no estado JA E o atual — `maxHp` e o teto.

    Nao existe campo `damage`: conferido no engine ao vivo e nos episodios.
    O codigo antigo fazia `hp - damage`, que dava o resultado certo por acaso
    (damage ausente vira 0), mas descrevia errado o que o engine entrega.
    """
    if pk is None:
        return 0.0
    return float(_campo(pk, "hp", 0) or 0)


# Ligados por variavel de ambiente para poder medir no painel contra `atual`.
USAR_DANO_REAL = os.environ.get("PTCG_DANO_REAL", "0") == "1"
USAR_DANO_FRACAO = os.environ.get("PTCG_DANO_FRACAO", "0") == "1"


def _dano_acumulado(pk) -> float:
    """Dano ja marcado neste Pokemon: `maxHp - hp`, em valor absoluto.

    BUG VIVO ATE AQUI. `avaliar_estado` pontuava o progresso contra o ativo
    dele com `_campo(ativo_dele, "damage", 0)`, e o campo `damage` NAO EXISTE:
    conferido em 2.258 Pokemon observados em partida, zero o traziam — enquanto
    429 deles estavam feridos. O termo W_DANO=2,0 valia zero em toda partida ja
    jogada, inclusive nas que estao na ladder.
    """
    if pk is None or not USAR_DANO_REAL:
        return 0.0
    maximo = float(_campo(pk, "maxHp", 0) or 0)
    atual = float(_campo(pk, "hp", 0) or 0)
    return max(0.0, maximo - atual)


def _fracao_derrubada(pk) -> float:
    """Quanto do ativo dele ja caiu, de 0 a 1.

    Por que FRACAO e nao dano absoluto, e por que isso nao e detalhe: ligar o
    termo absoluto com o peso que ja estava no codigo (W_DANO=2,0) custou
    -11,46pp no painel, IC [-17,28; -5,63], regredindo em tres das quatro
    casas. A conta explica sozinha — um ativo com 190 de dano marcado valia
    190x2 = 380, e derruba-lo valia W_KO = 300. A avaliacao pagava MAIS por
    deixar o adversario quase morto do que por mata-lo.
    """
    if pk is None:
        return 0.0
    maximo = float(_campo(pk, "maxHp", 0) or 0)
    if maximo <= 0:
        return 0.0
    return min(1.0, max(0.0, (maximo - float(_campo(pk, "hp", 0) or 0)) / maximo))


# BUG CORRIGIDO em 2026-08-11: o Pokemon EM JOGO nao expoe `ex` nem `megaEx`.
# Os campos dele sao appearThisTurn, energies, energyCards, hp, id, maxHp,
# playerIndex, preEvolution, serial, tools — e mais nada. Lendo `ex` de la, a
# funcao devolvia 1 para tudo, e a penalidade de letal nunca escalava por
# premio. Isso valeu para a versao que PASSOU no painel (+1,25pp): o ganho veio
# do resto do termo, com esta parte inerte.
#
# A identidade da carta vem do card data, como o agente de LB ~950 tambem faz.
_PREMIOS = {}
if _HAVE_CG:
    for _c in (_CARDS or []):
        try:
            _PREMIOS[_c.cardId] = 3 if _c.megaEx else 2 if _c.ex else 1
        except Exception:
            pass


def _premios_que_vale(pk) -> int:
    """Quantos premios o adversario leva ao nocautear este Pokemon."""
    if pk is None:
        return 0
    return _PREMIOS.get(_campo(pk, "id"), 1)


# Ligado por variavel de ambiente para poder medir no painel contra `atual`.
USAR_AMEACA_FRAQUEZA = os.environ.get("PTCG_AMEACA_FRAQUEZA", "0") == "1"


def _ameaca(jogador, meu_ativo=None, estado=None, com_fraqueza=None) -> int:
    """Maior dano que o campo dele faz no proximo turno, supondo +1 energia.

    Nao simula: le o campo, conta energia e consulta a tabela. Custa
    microssegundos, contra os 16,6 ms que simular o turno dele custava — e que
    ainda por cima piorava o resultado.

    Com `meu_ativo`, aplica fraqueza e resistencia. Isso importa muito mais do
    que parece: fraqueza DOBRA o dano (medido no engine, 17/17 casos com razao
    exata 2,0), entao a ameaca sem fraqueza erra por um fator de dois
    exatamente nas posicoes em que o nosso ativo morre — e o comentario deste
    mesmo bloco ja dizia que "subestimar e o erro que mata".
    """
    if not DANO_POR_ENERGIA:
        return 0
    usar = USAR_AMEACA_FRAQUEZA if com_fraqueza is None else com_fraqueza
    defensor_id = _campo(meu_ativo, "id") if (
        usar and meu_ativo is not None) else None
    reducao = _reducao_do_defensor(meu_ativo, estado) if defensor_id is not None else 0
    pior = 0
    ativo = _campo(jogador, "active") or []
    for pk in list(ativo) + list(_campo(jogador, "bench") or []):
        if pk is None:
            continue
        linha = DANO_POR_ENERGIA.get(_campo(pk, "id"))
        if not linha:
            continue
        # +1 energia: o anexo do turno dele
        e = min(_conta_energia(pk) + 1, 4)
        if e >= 1:
            bruto = linha[e - 1]
            if defensor_id is not None:
                bruto = _dano_efetivo(bruto, _campo(pk, "id"), defensor_id,
                                      reducao)
            pior = max(pior, bruto)
    return pior


def _conta_energia(pk) -> int:
    """Energias anexadas. O engine expoe `energies` e `energyCards` conforme o
    formato; ler os dois evita depender de qual veio."""
    if pk is None:
        return 0
    for nome in ("energies", "energyCards"):
        v = _campo(pk, nome)
        if isinstance(v, list):
            return len(v)
    return 0


def _primeiro(lista):
    return lista[0] if isinstance(lista, list) and lista else None


# ---------------------------------------------------------------------------
# OVERRIDE DE VITORIA IMEDIATA
#
# Se um ataque fecha a partida agora, ele nao precisa de busca — precisa ser
# jogado. A conta custa microssegundos e nao depende do rollout, que e o
# gargalo medido do agente.
#
# HONESTIDADE SOBRE O TAMANHO DISSO. A motivacao original era que 18% das
# vitorias ao alcance se perdiam apesar de `avaliar_estado` devolver 1e9 na
# vitoria. Duas explicacoes foram testadas e as duas cairam:
#
#   determinizacao  igualando a do agente e a da medicao, a perda continuou
#                   (16 de 88)
#   horizonte       `_rodar_ate_fim_do_turno` volta quando `yourIndex` muda, e
#                   parecia parar antes de o engine escrever `result`. Medido
#                   na MESMA sessao de busca: 36 de 36 ataques vencedores
#                   pontuam 1e9. A busca enxerga.
#
# O que restou e que aquele "18%" comparava DUAS sessoes de busca diferentes,
# com decks de determinizacao diferentes. Era artefato de medicao.
#
# Validado contra o forward model em 60 partidas: 17 disparos, 17 acertos,
# zero falso positivo — e so 2 mudaram a jogada.
#
# NAO PASSOU NO PAINEL, e a previsao registrada antes de rodar era essa: duas
# decisoes em 60 partidas e pequeno demais para o gate resolver. Com 21.600
# partidas por variante, +0,23pp, IC [-0,68; +1,14]. O intervalo cobre o zero
# com folga.
#
# Fica DESLIGADO. O codigo permanece porque a conta esta certa e e gratuita, e
# porque ela vira util no dia em que o deck tiver ataque de dano fixo que a
# busca nao alcance — mas entrar sem passar no painel e exatamente o que o gate
# existe para impedir. Ver docs/experimentos-2026-08-11-fraqueza-e-dano.md.
#
# Por que so ATAQUE DIRETO: repetindo K=5 vezes, em sessoes independentes, cada
# opcao que vencia na varredura:
#
#   tipo      opcoes   venceu 5/5
#   ATTACK        27     27 (100%)
#   EVOLVE        28     22
#   ATTACH        66     44
#   PLAY          21     11
#
# Vitoria por ATAQUE DIRETO e um fato deterministico; as outras sao sequencias
# cuja conclusao depende do rollout e da sorte da simulacao. Por isso o override
# cobre SO o ataque direto: e a unica classe em que uma conta fechada e tao boa
# quanto simular, e ela nao depende do gargalo medido (o rollout).
#
# Regras de dano CONFERIDAS no engine, nao supostas (jogos reais, casando cada
# log ATTACK com o HP_CHANGE que ele causou):
#
#   neutro       180/180 exato          razao 1,0
#   fraqueza      17/17                 razao 2,0  (x2)
#   resistencia   32/36                 -30, com piso em 0
#
# O par sample x lucario nao produz um unico caso de fraqueza (WATER contra
# fraqueza 5/1, FIGHTING contra fraqueza 4/8) — a sonda so achou os casos ao
# rodar os seis arquetipos do meta uns contra os outros.
# ---------------------------------------------------------------------------

def _int_ou_none(v):
    """EnergyType (IntEnum) ou None -> int ou None."""
    if v is None:
        return None
    try:
        return int(getattr(v, "value", v))
    except (TypeError, ValueError):
        return None


# Identidade de carta: o Pokemon EM JOGO nao expoe energyType, weakness nem
# resistance. Vem do card data por id, mesmo padrao do _PREMIOS.
_TIPO_CARTA: dict = {}
_FRAQUEZA: dict = {}
_RESISTENCIA: dict = {}
if _HAVE_CG:
    for _c in (_CARDS or []):
        try:
            _TIPO_CARTA[_c.cardId] = _int_ou_none(_c.energyType)
            _FRAQUEZA[_c.cardId] = _int_ou_none(_c.weakness)
            _RESISTENCIA[_c.cardId] = _int_ou_none(_c.resistance)
        except Exception:
            pass

MULTIPLICADOR_FRAQUEZA = 2
DESCONTO_RESISTENCIA = 30

# Entra por variavel de ambiente para poder medir no painel contra `atual`.
USAR_VITORIA_IMEDIATA = os.environ.get("PTCG_VITORIA_IMEDIATA", "0") == "1"

# Ataques cujo dano e CERTO. Fonte: all_attack() do proprio engine, nao o CSV.
#
# A diferenca nao e cosmetica. `DANO_DO_ATAQUE`, derivado do CSV, le o numero
# que abre o campo Damage: "30x" vira 30. O engine devolve `damage=0` para
# esses, porque o dano depende de moeda ou de contagem. Sao 110 ataques em que
# o CSV afirma dano garantido e o piso real e ZERO — Comet Punch (30), Double
# Hit (90), Cross Breaker (120). Para AMEACA superestimar e o lado seguro e o
# CSV serve; para LETAL e o contrario, e usar a tabela do CSV aqui seria atacar
# achando que mata, nao matar, e perder o turno.
#
# O filtro de texto precisa mirar so o que baixa o dano DESTE ataque. A
# primeira versao barrava qualquer "less damage" e "coin", e a medicao mostrou
# o preco: cobertura de 1,5%, porque ela matou justamente o Frost Barrier — o
# ataque de 200 do deck do sample, cujo texto e "this Pokemon takes 30 less
# damage", um efeito DEFENSIVO. Lendo os 1.175 ataques com dano > 0, so tres
# familias de frase abaixam o proprio dano:
#
#   "this attack does nothing"           24 ataques
#   "this attack does N less damage"      2
#   "instead"                             1
#
# Moeda, sozinha, nunca abaixa: dos 73 ataques com "coin" e sem "does nothing",
# todos os efeitos ou SOMAM dano ou aplicam condicao especial.
_TEXTO_INSEGURO = None  # compilado abaixo; regex, nao substring

_ATAQUE_DANO: dict = {}
if _HAVE_CG:
    try:
        import re as _re
        from cg.api import all_attack as _all_attack
        _TEXTO_INSEGURO = _re.compile(
            r"this attack does nothing|this attack does \d+ less damage|instead",
            _re.I)
        for _a in _all_attack():
            if _a.damage > 0 and not _TEXTO_INSEGURO.search(getattr(_a, "text", "") or ""):
                _ATAQUE_DANO[_a.attackId] = int(_a.damage)
    except Exception:
        _ATAQUE_DANO = {}  # sem tabela o override simplesmente nao dispara


# Ataques que escalam com a energia dos DOIS ativos.
#
# Isto existe por causa do Boss's Orders. O Myriad Leaf Shower soma 30 por
# energia anexada aos dois ativos — entao a energia do ALVO e um multiplicador
# do NOSSO dano, e arrastar um Pokemon carregado aumenta o nosso golpe:
#
#     4 energias minhas, alvo com 0 energia  ->  150
#     4 energias minhas, alvo com 4 energias ->  270
#
# DANO_POR_ENERGIA nao serve aqui: ela e indexada so pela MINHA energia e satura
# em 4, entao perde exatamente o termo que decide a escolha do alvo.
#
# Le do TEXTO do ataque, nao por id. Cravar id foi o erro do agente de LB ~950
# que medimos custar 37pp quando o deck muda.
_ESCALA_DOIS_ATIVOS: dict = {}
if _HAVE_CG:
    try:
        import re as _re2
        from cg.api import all_attack as _all_attack2
        _R_ESCALA = _re2.compile(
            r"does (\d+) more damage for each Energy attached to both Active",
            _re2.I)
        for _a in _all_attack2():
            _m = _R_ESCALA.search(getattr(_a, "text", "") or "")
            if _m:
                _ESCALA_DOIS_ATIVOS[_a.attackId] = int(_m.group(1))
    except Exception:
        _ESCALA_DOIS_ATIVOS = {}


# cardId -> ataques daquele Pokemon. Sem isto, procurar "o meu melhor ataque"
# varreria os 1.148 ataques do jogo e escolheria o maior de todos.
#
# A carta tem DOIS campos parecidos: `skills` sao as HABILIDADES (o Teal Dance,
# com name e text) e `attacks` e uma lista de attackId JA COMO INTEIROS — nao
# objetos. Duas versoes disto sairam vazias antes de eu olhar o dado: uma leu
# `skills`, a outra procurou `.attackId` dentro de um int.
_ATAQUES_DA_CARTA: dict = {}
if _HAVE_CG:
    try:
        for _c in (_CARDS or []):
            _ids = {int(_a) for _a in (getattr(_c, "attacks", None) or [])}
            if _ids:
                _ATAQUES_DA_CARTA[_c.cardId] = _ids
    except Exception:
        _ATAQUES_DA_CARTA = {}


def _ataque_do_pokemon(card_id, atk_id) -> bool:
    ids = _ATAQUES_DA_CARTA.get(card_id)
    return bool(ids) and atk_id in ids


# Quanto cada carta ANEXAVEL ou de campo tira do dano recebido, lido do texto
# da propria carta. Sao poucas — quatro ferramentas e dois estadios — mas
# desistir da posicao sempre que houvesse ferramenta custava 12 dos 49 casos de
# cobertura perdida, e ferramenta que nao mexe em dano e a maioria.
#
# Lido do texto, nao cravado por id: e a mesma diferenca que separa a nossa
# tabela de dano (1.004 cartas, geradas) da do agente de LB ~950 (seis cartas
# no codigo). O desconto e o PIOR CASO — supoe que a reducao sempre se aplica,
# mesmo quando ela e condicional ao tipo do atacante.
_REDUCAO_CARTA: dict = {}
if _HAVE_CG:
    try:
        import re as _re2
        _R_MENOS = _re2.compile(r"(\d+)\s+less damage", _re2.I)
        for _c in (_CARDS or []):
            try:
                if int(getattr(_c, "cardType", 0)) == 0:
                    continue  # Pokemon nao e ferramenta nem estadio
                txt = " ".join((getattr(s, "text", "") or "")
                               for s in (getattr(_c, "skills", None) or []))
                vals = [int(v) for v in _R_MENOS.findall(txt)]
                if vals:
                    _REDUCAO_CARTA[_c.cardId] = max(vals)
            except Exception:
                pass
    except Exception:
        pass


def _reducao_do_defensor(defensor, estado) -> int:
    """Dano que o defensor evita por ferramenta anexada e por estadio em jogo."""
    total = 0
    for t in (_campo(defensor, "tools") or []):
        total += _REDUCAO_CARTA.get(_campo(t, "id"), 0)
    for s in (_campo(estado, "stadium") or []):
        total += _REDUCAO_CARTA.get(_campo(s, "id"), 0)
    return total


def _dano_efetivo(base: int, atacante_id, defensor_id, reducao: int = 0) -> int:
    """Dano no ativo dele, com fraqueza e resistencia. Piso em 0.

    A ordem importa e e a das cartas: fraqueza multiplica, resistencia e as
    reducoes subtraem depois ("after applying Weakness and Resistance", como o
    texto das proprias ferramentas diz).
    """
    tipo = _TIPO_CARTA.get(atacante_id)
    d = int(base)
    if tipo is not None:
        if _FRAQUEZA.get(defensor_id) == tipo:
            d *= MULTIPLICADOR_FRAQUEZA
        if _RESISTENCIA.get(defensor_id) == tipo:
            d -= DESCONTO_RESISTENCIA
    return max(0, d - max(0, int(reducao)))


def vitoria_imediata(obs_dict) -> int | None:
    """Indice da opcao de ataque que GANHA a partida agora, ou None.

    Conservador de proposito: so devolve indice quando a conta fecha por
    inteiro. Cada porta fechada abaixo e uma forma conhecida de o numero mentir.
    """
    if not _ATAQUE_DANO:
        return None
    sel = (obs_dict or {}).get("select") or {}
    opcoes = sel.get("option") or []
    if not opcoes or int(sel.get("maxCount", 1) or 1) != 1:
        return None

    estado = (obs_dict or {}).get("current") or {}
    jogadores = estado.get("players") or []
    if len(jogadores) < 2:
        return None
    eu = int(estado.get("yourIndex", 0))
    meu, dele = jogadores[eu] or {}, jogadores[1 - eu] or {}

    # Confusao faz o ataque depender de moeda: a conta deixa de valer.
    if meu.get("confused"):
        return None

    atacante = _primeiro(meu.get("active"))
    defensor = _primeiro(dele.get("active"))
    if atacante is None or defensor is None:
        return None

    hp = _hp_efetivo(defensor)
    if hp <= 0:
        return None

    # Nocautear so fecha a partida por uma destas duas portas.
    premios_restantes = len(meu.get("prize") or [])
    fecha_por_premio = _premios_que_vale(defensor) >= premios_restantes > 0
    fecha_por_campo = not (dele.get("bench") or [])
    if not (fecha_por_premio or fecha_por_campo):
        return None

    atacante_id = _campo(atacante, "id")
    defensor_id = _campo(defensor, "id")
    reducao = _reducao_do_defensor(defensor, estado)
    for i, op in enumerate(opcoes):
        if _opt_type(op) != OPT_ATTACK:
            continue
        base = _ATAQUE_DANO.get(_opt_field(op, "attackId"))
        if base is None:
            continue
        if _dano_efetivo(base, atacante_id, defensor_id, reducao) >= hp:
            return i
    return None


# ---------------------------------------------------------------------------
# PROTEGER O ATIVO DO NOCAUTE
#
# O pedido, na voz do Fernando: "apontar casos onde uma carta salva um Pokemon
# meu de ser nocauteado" e "criar o plano de quando usar as cartas que curam
# HP, para nao usar de forma indevida".
#
# As duas frases sao a MESMA regra, e ela e uma so:
#
#     so gasta a carta quando ela MUDA O DESFECHO.
#
# Curar 80 de um Ogerpon que sobreviveria de qualquer jeito e jogar a carta
# fora. Curar 80 de um que morre mesmo depois da cura tambem e. A carta so vale
# no meio: quando a ameaca mata AGORA e deixa de matar DEPOIS.
#
# O que torna isto possivel agora e a ameaca com fraqueza: sem ela, o numero de
# entrada erra por um fator de dois exatamente contra quem nos mata.
#
# Por que e barato: nem o Jumbo Ice Cream (Item) nem o Hero's Cape (Tool)
# ENCERRAM O TURNO. Jogar a carta nao custa o ataque — custa so a carta. E por
# isso o override pode disparar antes da busca sem tirar nada dela.
#
# No deck do Ogerpon isto vale, em numeros medidos:
#
#   Mega Kangaskhan ex, 13,5% do campo, Rapid-Fire Combo = 200 + 50 por cara
#   contra os 210 do Ogerpon:  P(nocaute de um golpe) = 50,0%
#   com o Hero's Cape (+100), HP 310:                    12,5%
#
# As cartas NAO sao cravadas por id: o efeito sai do texto da propria carta,
# como a tabela de dano. Cravar id foi o erro do agente de LB ~950 que medimos
# custar 37pp quando o deck muda.
# ---------------------------------------------------------------------------

USAR_PROTECAO = os.environ.get("PTCG_PROTEGER", "0") == "1"

_R_HP_EXTRA = None
_R_CURA = None
_PROTECAO: dict = {}   # cardId -> (hp_extra_permanente, cura_no_ativo)
if _HAVE_CG:
    try:
        import re as _re3
        _R_HP_EXTRA = _re3.compile(r"gets \+(\d+) HP", _re3.I)
        _R_CURA = _re3.compile(r"Heal (\d+) damage from your Active", _re3.I)
        for _c in (_CARDS or []):
            try:
                txt = " ".join((getattr(s, "text", "") or "")
                               for s in (getattr(_c, "skills", None) or []))
                if not txt:
                    continue
                mh = _R_HP_EXTRA.search(txt)
                mc = _R_CURA.search(txt)
                if mh or mc:
                    _PROTECAO[_c.cardId] = (int(mh.group(1)) if mh else 0,
                                            int(mc.group(1)) if mc else 0)
            except Exception:
                pass
    except Exception:
        _PROTECAO = {}


def _hp_apos_protecao(ativo, extra: int, cura: int) -> float:
    """HP do ativo depois da carta. A cura tem teto no maxHp; o +HP sobe o teto."""
    hp = _hp_efetivo(ativo)
    maximo = float(_campo(ativo, "maxHp", 0) or 0)
    if cura:
        hp = min(maximo, hp + cura) if maximo > 0 else hp + cura
    return hp + extra


def proteger_do_nocaute(obs_dict) -> int | None:
    """Indice da carta que transforma "morro no proximo turno" em "sobrevivo".

    None quando nao ha o que salvar (a ameaca nao mata) ou quando nao ha
    salvacao (mata mesmo com a carta). Nos dois casos, guardar a carta e a
    jogada certa.

    Entre varias que salvam, escolhe a de MENOR protecao suficiente: gastar o
    Hero's Cape (+100, ACE SPEC, copia unica) num vulto que 20 de HP resolviam
    e o mesmo desperdicio, so mais caro.
    """
    if not _PROTECAO or not DANO_POR_ENERGIA:
        return None
    sel = (obs_dict or {}).get("select") or {}
    opcoes = sel.get("option") or []
    if not opcoes or int(sel.get("maxCount", 1) or 1) != 1:
        return None

    estado = (obs_dict or {}).get("current") or {}
    jogadores = estado.get("players") or []
    if len(jogadores) < 2:
        return None
    eu = int(estado.get("yourIndex", 0))
    meu, dele = jogadores[eu] or {}, jogadores[1 - eu] or {}

    ativo = _primeiro(meu.get("active"))
    if ativo is None:
        return None

    # fraqueza SEMPRE ligada aqui, independente da flag da avaliacao: sem ela a
    # ameaca erra por um fator de dois exatamente contra quem nos mata, e e
    # esse numero que decide se a carta e gasta ou guardada
    ameaca = _ameaca(dele, ativo, estado, com_fraqueza=True)
    if not ameaca or ameaca < _hp_efetivo(ativo):
        return None  # nao morre no proximo turno: nao ha o que proteger

    melhor_i, melhor_custo = None, None
    for i, op in enumerate(opcoes):
        t = _opt_type(op)
        if t not in (OPT_PLAY, OPT_TOOL_CARD, OPT_CARD, OPT_ATTACH):
            continue
        cid = _carta_da_opcao(op, estado, sel, eu)
        prot = _PROTECAO.get(cid)
        if not prot:
            continue
        extra, cura = prot
        # protecao anexada tem que ir para o ATIVO, nao para o banco
        area = _opt_field(op, "inPlayArea")
        if extra and isinstance(area, int) and area != AREA_ACTIVE:
            continue
        if ameaca < _hp_apos_protecao(ativo, extra, cura):
            custo = extra + cura  # a menor protecao que basta
            if melhor_custo is None or custo < melhor_custo:
                melhor_i, melhor_custo = i, custo
    return melhor_i


def avaliar_estado(estado, meu_indice: int) -> float:
    """Pontua um estado do ponto de vista de `meu_indice`. Maior e melhor."""
    jogadores = _campo(estado, "players") or []
    if len(jogadores) < 2:
        return 0.0
    eu = jogadores[meu_indice]
    ele = jogadores[1 - meu_indice]

    vencedor = _campo(estado, "result", -1)
    if vencedor == meu_indice:
        return 1e9
    if vencedor == 1 - meu_indice:
        return -1e9

    # Premios: quem tem MENOS premios restantes esta mais perto de ganhar.
    s = (len(_campo(ele, "prize") or []) - len(_campo(eu, "prize") or [])) * W_PREMIO

    meu_ativo = _primeiro(_campo(eu, "active"))
    ativo_dele = _primeiro(_campo(ele, "active"))
    if HP_INVARIANTE:
        campo = [pk for pk in [meu_ativo] + list(_campo(eu, "bench") or [])
                 if pk is not None]
        if HP_INVARIANTE == 2:
            # forma 2: vida total do campo. Invariante ao recuo, mas paga por
            # ter mais Pokemon em jogo.
            s += sum(float(_campo(pk, "hp", 0) or 0) for pk in campo) * W_HP
        else:
            # forma 1: dano acumulado no campo. Invariante ao recuo E ao numero
            # de Pokemon — um Pokemon novo contribui zero.
            s -= sum(max(0.0, float(_campo(pk, "maxHp", 0) or 0)
                         - float(_campo(pk, "hp", 0) or 0))
                     for pk in campo) * W_HP
    else:
        s += _hp_efetivo(meu_ativo) * W_HP
    if ativo_dele is not None:
        # Progresso contra o ativo dele vale, NO MAXIMO, o que vale derruba-lo:
        # a fracao vai de 0 a 1 e multiplica o proprio W_KO, entao um ativo
        # quase morto nunca ultrapassa um ativo morto. Sem constante nova —
        # inventar um peso aqui seria inventar exatamente a folga que fez a
        # versao absoluta perder 11pp.
        if USAR_DANO_FRACAO:
            s += _fracao_derrubada(ativo_dele) * W_KO
        s += _dano_acumulado(ativo_dele) * W_DANO
    else:
        s += W_KO  # sem ativo em campo = acabou de cair

    s += len(_campo(eu, "bench") or []) * W_BANCO
    if BANCO_DELE:
        s -= len(_campo(ele, "bench") or []) * W_BANCO
    if ENERGIA_DO_ALVO and ativo_dele is not None:
        # a energia DELE e multiplicador do NOSSO dano — ver o bloco acima
        s += _conta_energia(ativo_dele) * W_ENERGIA
    if ENERGIA_DELE_CONTRA and ativo_dele is not None:
        # sinal invertido do de cima: nocautear um alvo carregado apaga a
        # energia dele, e o termo paga por isso
        s -= _conta_energia(ativo_dele) * W_ENERGIA
    if W_ENERGIA:
        # Energia no ativo e energia no banco NAO sao a mesma coisa: o Myriad
        # Leaf Shower conta a dos dois ATIVOS. Com FRACAO_ENERGIA_BANCO = 1,0
        # (o padrao) isto e identico ao que existia antes; abaixo de 1, a
        # avaliacao passa a preferir a energia no atacante — e e ela que
        # desempata a habilidade do ativo contra a do banco.
        no_banco = 0
        for pk in _campo(eu, "bench") or []:
            no_banco += _conta_energia(pk)
        s += (_conta_energia(meu_ativo)
              + no_banco * FRACAO_ENERGIA_BANCO) * W_ENERGIA

    if (W_AMEACA or W_LETAL) and meu_ativo is not None:
        ameaca = _ameaca(ele, meu_ativo, estado)
        if ameaca:
            if ameaca >= _hp_efetivo(meu_ativo):
                # morre no proximo turno: custa os premios que ele vale
                s -= _premios_que_vale(meu_ativo) * W_LETAL
            else:
                s -= ameaca * W_AMEACA

    if W_DECKOUT:
        restam = float(_campo(eu, "deckCount", 60) or 0)
        if restam < 8:
            s -= (8 - restam) * W_DECKOUT
    return s


# L1c: avaliar o TURNO, nao a jogada. Ver docs/plano-L1c.md.
# O turno do PTCG tem varias acoes e so termina no ataque; avaliar 1 ply compara
# jogadas que ainda vao ser seguidas por outras. Aqui cada ramo e conduzido pela
# propria L0 ate o turno fechar, e so entao avaliado.
AVALIAR_TURNO_INTEIRO = True
MAX_PASSOS_TURNO = 40


def _politica_condutora(estado_busca) -> list[int]:
    """Politica que conduz a simulacao dentro de um ramo.

    Precisa ser a MESMA em todos os ramos, para que a diferenca venha da
    primeira escolha. Com o prior ligado, ela deixa de ser a L0 pura: e aqui
    que a qualidade do rollout entra, e medimos que o rollout e o gargalo —
    das 247 chances de nocaute o agente perde 42, e das 105 de vitoria perde 19,
    com a avaliacao ja devolvendo 1e9 na vitoria.

    RESSALVA (11/08): a parte de VITORIA desse numero nao se sustentou. Ela
    comparava duas sessoes de busca diferentes, com determinizacoes
    diferentes; medido dentro de UMA sessao, 36 de 36 ataques vencedores
    pontuam 1e9. A parte de NOCAUTE nao foi remedida.
    Ver docs/experimentos-2026-08-11-fraqueza-e-dano.md.
    """
    sel = _campo(estado_busca, "select")
    opcoes = _campo(sel, "option") or []
    if not opcoes:
        return []
    mn = int(_campo(sel, "minCount", 1) or 1)
    mx = int(_campo(sel, "maxCount", 1) or 1)
    notas = score_options(opcoes, estado_busca)
    if W_PRIOR:
        p = pontuar_com_prior(estado_busca)
        if p and len(p) == len(notas):
            # sem `strict=`: o tamanho ja foi conferido na linha acima, e o
            # agente NAO PODE levantar dentro do container — estourar e derrota
            notas = [n + W_PRIOR * pi for n, pi in zip(notas, p)]  # noqa: B905
    return select_indices(notas, mn, mx)


