# L2 — continuar a simulacao pelo turno do ADVERSARIO.
#
# Por que: a busca de 1 ply para quando o meu turno acaba, entao "eu mato" e "eu
# morro" nao existem na avaliacao. E a cegueira mais antiga do projeto, e nenhum
# peso na avaliacao conserta — foram tres hipoteses testadas e rejeitadas
# (prioridade da habilidade, energia na avaliacao, determinizacao embaralhada).
# O problema nao e quanto cada termo pesa, e QUE estado se avalia.
#
# O orcamento comporta com folga: ~5 ms por decisao medidos contra 4,3 s
# disponiveis. Entra por variavel de ambiente para poder medir contra o 1 ply.
PLY = int(os.environ.get("PTCG_PLY", "1"))
MAX_PASSOS_OPONENTE = 60


def _rodar_turno_do_oponente(passo_fn, estado_busca, meu_indice: int, prazo: float):
    """Avanca a simulacao pelo turno dele, ate a vez voltar ou a partida acabar.

    Conduzido pela mesma L0, como o meu turno: nao precisa ser boa, precisa ser
    a MESMA em todos os ramos, para que a diferenca venha da primeira escolha.
    """
    atual = estado_busca
    for _ in range(MAX_PASSOS_OPONENTE):
        if time.time() > prazo:
            return atual
        obs = getattr(atual, "observation", None)
        estado = _campo(obs, "current")
        if _campo(estado, "result", -1) != -1:
            return atual  # acabou: e o desfecho que importa
        if _campo(estado, "yourIndex", meu_indice) == meu_indice:
            return atual  # a vez voltou: o turno dele fechou
        sel = _campo(obs, "select")
        if not sel or not (_campo(sel, "option") or []):
            return atual
        escolha = _politica_condutora(obs)
        if not escolha:
            return atual
        try:
            atual = passo_fn(atual.searchId, escolha)
        except Exception:
            return atual
    return atual


def _rodar_ate_fim_do_turno(passo_fn, estado_busca, meu_indice: int, prazo: float):
    """Avanca a simulacao com a L0 ate o turno deixar de ser meu."""
    atual = estado_busca
    for _ in range(MAX_PASSOS_TURNO):
        if time.time() > prazo:
            return atual
        obs = getattr(atual, "observation", None)
        estado = _campo(obs, "current")
        if _campo(estado, "result", -1) != -1:
            return atual  # partida acabou: este e o estado final que importa
        if _campo(estado, "yourIndex", meu_indice) != meu_indice:
            return atual  # passou a vez — o turno fechou
        sel = _campo(obs, "select")
        if not sel or not (_campo(sel, "option") or []):
            return atual
        escolha = _politica_condutora(obs)
        if not escolha:
            return atual
        try:
            atual = passo_fn(atual.searchId, escolha)
        except Exception:
            return atual
    return atual


# L3 — busca em FEIXE sobre o turno inteiro.
#
# O que ela substitui: hoje cada opcao e avaliada steppando uma vez e deixando a
# L0 conduzir o resto do turno. Isso torna a L0 a avaliacao de fato — a busca so
# distingue duas opcoes na medida em que a continuacao da L0 difere. Medido:
# das 247 chances de nocaute, o agente perde 42 (17%); das 105 chances de
# VENCER na hora, perde 19 (18%). A avaliacao ja devolve 1e9 na vitoria, entao
# quem perde essas 19 e o rollout, que nao completa a sequencia.
#
# Aqui o turno vira o que ele e: uma SEQUENCIA de jogadas. O feixe mantem as
# `largura` melhores sequencias parciais e expande todas, em vez de seguir uma
# linha fixa. Cada opcao da raiz recebe o MELHOR valor terminal alcancavel a
# partir dela.
#
# Custo: largura x profundidade x opcoes x 0,11 ms. Com largura 8, ~20 jogadas
# por turno e ~10 opcoes, da ~180 ms — contra 4.300 ms de orcamento.
# DESLIGADA por padrao. Historia curta, porque ela e instrutiva:
#
# Contra UM oponente (ref950 com o deck dele, 0,05 s) a largura 4 deu 18,0%
# [16,6; 19,5] contra 15,7% [14,3; 17,1] do rollout — +2,33pp, p=0,022, N=2.700
# de cada lado. Submeti como melhoria validada (S8).
#
# No PAINEL, com N maior, o ganho evaporou:
#
#   variante   ref950+Luc  ref950+Luc   ref950+   primeira   TOTAL
#              0,05s       0,5s         sample    (piso)
#   rollout    16,7%       16,5%        53,9%     57,9%      36,2%
#   feixe 4    16,7%       17,8%        52,0%     55,4%      35,5%
#
#   -0,76pp  IC [-1,87; +0,34]  NAO PASSA
#
# Empata nos dois oponentes duros e PERDE nos dois faceis. Aquele +2,33pp era
# regressao a media disfarcada de significancia — exatamente o que a regra de
# replicas do projeto existe para pegar, e que eu contornei por ter medido
# contra uma referencia so.
#
# O codigo fica porque a busca em feixe continua sendo a ideia certa; o que
# falta e a avaliacao que ela usa, que e a mesma linear de 4 termos ja esgotada.
# Custo, se ligada: ~37 ms por decisao de 4.300 disponiveis.
LARGURA_FEIXE = int(os.environ.get("PTCG_FEIXE", "0"))  # 0 = desliga
MAX_NIVEIS_FEIXE = 24


def _expandir_feixe(passo_fn, raiz, n_opcoes, eu, prazo, largura):
    """Devolve a melhor nota terminal alcancavel por cada opcao da raiz."""
    melhor = [float("-inf")] * n_opcoes

    # nivel 0: uma semente por opcao da raiz
    feixe = []
    for i in range(n_opcoes):
        if time.time() > prazo:
            break
        try:
            est = passo_fn(raiz.searchId, [i])
        except Exception:
            continue
        feixe.append((est, i))

    for _ in range(MAX_NIVEIS_FEIXE):
        if not feixe or time.time() > prazo:
            break
        seguintes = []
        for est, origem in feixe:
            obs = getattr(est, "observation", None)
            atual = _campo(obs, "current")

            # terminal: a partida acabou ou o turno fechou
            if (_campo(atual, "result", -1) != -1
                    or _campo(atual, "yourIndex", eu) != eu):
                v = avaliar_estado(atual, eu)
                if v > melhor[origem]:
                    melhor[origem] = v
                continue

            sel = _campo(obs, "select")
            opcoes = _campo(sel, "option") or []
            if not opcoes:
                v = avaliar_estado(atual, eu)
                if v > melhor[origem]:
                    melhor[origem] = v
                continue

            mn = int(_campo(sel, "minCount", 1) or 1)
            mx = int(_campo(sel, "maxCount", 1) or 1)
            if mn != 1 or mx != 1:
                # selecao multipla: nao ramifica, deixa a L0 resolver este passo
                escolha = select_indices(score_options(opcoes), mn, mx)
                try:
                    seguintes.append((passo_fn(est.searchId, escolha), origem))
                except Exception:
                    pass
                continue

            for j in range(len(opcoes)):
                if time.time() > prazo:
                    break
                try:
                    seguintes.append((passo_fn(est.searchId, [j]), origem))
                except Exception:
                    continue

        if not seguintes:
            break
        # poda: mantem as `largura` sequencias parciais mais promissoras
        seguintes.sort(
            key=lambda p: avaliar_estado(
                _campo(getattr(p[0], "observation", None), "current"), eu),
            reverse=True)
        feixe = seguintes[:largura]

    # o que sobrou no feixe quando o orcamento acabou tambem conta
    for est, origem in feixe:
        v = avaliar_estado(
            _campo(getattr(est, "observation", None), "current"), eu)
        if v > melhor[origem]:
            melhor[origem] = v
    return melhor


# ---------------------------------------------------------------------------
# Features do prior de politica — UMA implementacao, aqui.
#
# O treino le JSON de episodio e a inferencia le a observacao ao vivo. Se
# fossem dois extratores, divergiriam em silencio e o modelo viraria ruido sem
# nenhum erro aparecer. Por isso `tools/coletar_imitacao.py` IMPORTA daqui:
# uma implementacao nao pode divergir de si mesma.
#
# A observacao do episodio e a observacao ao vivo tem a mesma forma — as duas
# sao o mesmo dict que o engine produz.
# ---------------------------------------------------------------------------

AREA_DECK, AREA_HAND, AREA_DISCARD = 1, 2, 3
AREA_PRIZE, AREA_STADIUM, AREA_LOOKING = 6, 7, 12

CLASSES_CARTA = ("Basic Pokémon", "Stage 1 Pokémon", "Stage 2 Pokémon",
                 "Pokémon Tool", "Item", "Supporter", "Stadium",
                 "Special Energy", "Basic Energy")

NOMES_FEATURES = (
    "turno", "meus_premios", "premios_dele", "meu_hp", "hp_dele",
    "minha_energia", "energia_dele", "meu_banco", "banco_dele",
    "minha_mao", "mao_dele", "meu_deck", "apoiador_jogado",
    "energia_anexada", "recuou", "n_opcoes", "indice",
    "carta_ex", "carta_hp", "dano", "letal",
    # ACRESCENTADAS em 13/08. Ver o comentario em `features_da_decisao`: as
    # tabelas de dano exato, fraqueza e premios ja existiam no agente e nao
    # eram vistas pelo prior.
    "fracao_derrubada", "premios_do_alvo", "morro_no_proximo",
) + tuple(f"tipo_{t}" for t in range(17))   + tuple(f"classe_{c}" for c in CLASSES_CARTA)


def _lista(x):
    return x if isinstance(x, list) else []


def _carta_da_opcao(op, cur, sel, eu):
    """Posicao -> carta. So o tipo SKILL carrega cardId (75 de 187 mil opcoes),
    entao sem esta resolucao o modelo nao sabe o que a jogada mexe."""
    cid = _opt_field(op, "cardId")
    if isinstance(cid, int):
        return cid
    area, idx = _opt_field(op, "area"), _opt_field(op, "index")
    # BUG CORRIGIDO em 2026-08-12. Jogar uma carta da mao vem SEM `area`: a
    # opcao de Bug Catching Set e literalmente {'type': 7, 'index': 3}. Exigir
    # `area` fazia esta funcao devolver None para a maioria das jogadas —
    # medido em 12 partidas, 757 opcoes nao resolviam, sendo 488 Itens, 668
    # Apoiadores e 29 Estadios.
    #
    # O estrago tem dois endereços:
    #   1. as features do prior nao sabiam QUAL carta a jogada usa
    #   2. `proteger_do_nocaute` nao enxergava o Jumbo Ice Cream, que e Item
    #
    # Sem `area`, a carta vem da mao de quem esta jogando — e o unico lugar de
    # onde se joga uma carta.
    if area is None and idx is not None and _opt_type(op) in (
            OPT_PLAY, OPT_CARD, OPT_TOOL_CARD, OPT_ENERGY_CARD, OPT_DISCARD):
        area = AREA_HAND
    if area is None or idx is None:
        return None
    dono = _opt_field(op, "playerIndex")
    dono = eu if dono is None else int(dono)
    jog = (_campo(cur, "players") or [{}, {}])[dono] or {}
    fonte = {
        AREA_DECK: _campo(sel, "deck"),
        AREA_HAND: _campo(jog, "hand"),
        AREA_DISCARD: _campo(jog, "discard"),
        AREA_ACTIVE: _campo(jog, "active"),
        AREA_BENCH: _campo(jog, "bench"),
        AREA_PRIZE: _campo(jog, "prize"),
        AREA_STADIUM: _campo(cur, "stadium"),
        AREA_LOOKING: _campo(cur, "looking"),
    }.get(int(area))
    fonte = _lista(fonte)
    if not (0 <= int(idx) < len(fonte)):
        return None
    return _campo(fonte[int(idx)], "id")


def features_da_decisao(obs_dict, cartas_meta):
    """Vetor por opcao. `cartas_meta` mapeia cardId -> (tipo, ex, hp)."""
    cur = _campo(obs_dict, "current") or {}
    sel = _campo(obs_dict, "select") or {}
    opcoes = _campo(sel, "option") or []
    eu = int(_campo(cur, "yourIndex", 0) or 0)
    jog = _campo(cur, "players") or [{}, {}]
    meu, dele = jog[eu] or {}, jog[1 - eu] or {}
    meu_at = _primeiro(_campo(meu, "active"))
    dele_at = _primeiro(_campo(dele, "active"))

    contexto = [
        float(_campo(cur, "turn", 0) or 0),
        len(_lista(_campo(meu, "prize"))),
        len(_lista(_campo(dele, "prize"))),
        _hp_efetivo(meu_at), _hp_efetivo(dele_at),
        _conta_energia(meu_at), _conta_energia(dele_at),
        len(_lista(_campo(meu, "bench"))), len(_lista(_campo(dele, "bench"))),
        float(_campo(meu, "handCount", 0) or 0),
        float(_campo(dele, "handCount", 0) or 0),
        float(_campo(meu, "deckCount", 0) or 0),
        float(bool(_campo(cur, "supporterPlayed"))),
        float(bool(_campo(cur, "energyAttached"))),
        float(bool(_campo(cur, "retreated"))),
    ]

    # O dano e o letal desta opcao. ATE 13/08 os dois eram calculados errado, e
    # isso explica a divida registrada de que a feature `letal` estava
    # "invertida" (o professor executava o letal em 55,4% dos turnos em que ele
    # existia e atacava em 72,2% dos turnos em que NAO existia). Tres defeitos,
    # todos corrigidos aqui:
    #
    #   1. usava `DANO_BASE`, derivado do CSV, que afirma dano garantido em 110
    #      ataques cujo piso real e ZERO. Agora usa `_ATAQUE_DANO`, do
    #      `all_attack()` do proprio engine.
    #   2. indexava por CARTA e por energia, nao por ATAQUE. Um Pokemon com dois
    #      ataques marcava o mesmo dano nos dois — inclusive no fraco.
    #   3. ignorava fraqueza e resistencia, medidas no engine em 12/08
    #      (x2 e -30 com piso em 0). Contra um alvo fraco ao nosso tipo, o dano
    #      real e o DOBRO do que a feature dizia.
    #
    # Isto e a "opcao 1" de docs/destilacao-2026-08-13.md: o GBM ganha por
    # nao-linearidade sobre features fracas, entao dar features FORTES a
    # logistica pode valer mais que imitar a nao-linearidade.
    hp_alvo = _hp_efetivo(dele_at)
    meu_id = _campo(meu_at, "id") if meu_at else None
    alvo_id = _campo(dele_at, "id") if dele_at else None
    reducao_alvo = _reducao_do_defensor(dele_at, cur) if dele_at else 0

    # o que ELE nos faz no proximo turno — o outro lado da mesma moeda
    ameaca = _ameaca(dele, meu_at, cur, com_fraqueza=True) if meu_at else 0
    meu_hp = _hp_efetivo(meu_at)
    morro = float(ameaca >= meu_hp > 0)

    saida = []
    for i, op in enumerate(opcoes):
        cid = _carta_da_opcao(op, cur, sel, eu)
        meta = cartas_meta.get(cid) if cid is not None else None
        tipo = _opt_type(op)
        atacando = tipo == OPT_ATTACK and meu_at is not None and dele_at is not None

        dano_atq = 0.0
        if atacando:
            base = _ATAQUE_DANO.get(_opt_field(op, "attackId"))
            if base is not None:
                dano_atq = float(_dano_efetivo(base, meu_id, alvo_id,
                                               reducao_alvo))

        v = contexto + [
            float(len(opcoes)), float(i),
            float(bool(meta[1])) if meta else 0.0,          # carta_ex
            float(meta[2]) if meta else 0.0,                # carta_hp
            dano_atq,                                       # dano
            float(dano_atq >= hp_alvo > 0),                 # letal
            # fracao do alvo que este ataque derruba: 0,9 e muito diferente de
            # 0,1, e o `letal` binario perde essa distincao
            min(1.0, dano_atq / hp_alvo) if hp_alvo > 0 else 0.0,
            # quantos premios o alvo vale — nocautear um ex vale o dobro
            float(_premios_que_vale(dele_at)) if dele_at else 0.0,
            morro,          # eu morro no proximo turno se nao fizer nada
        ]
        v += [1.0 if tipo == t else 0.0 for t in range(17)]
        classe = meta[0] if meta else ""
        v += [1.0 if classe == c else 0.0 for c in CLASSES_CARTA]
        saida.append(v)
    return saida


