# ---------------------------------------------------------------------------
# A PARTE NAO-LINEAR DO PRIOR — arvores como constante.
#
# Por que existe: tres tentativas de melhorar o prior falharam, e o diagnostico
# foi o mesmo nas tres. Um gradient boosting acerta +1,97pp a mais que a
# logistica no top-1, e essa vantagem NAO e alcancavel por forma linear:
#
#   cruzamentos de features   -0,28pp   nao e interacao entre pares
#   destilar os logits        -0,87pp   nao e imitavel
#   features de dominio       +0,00pp   nao e falta de informacao
#
# E nao-linearidade pura: cortes em degrau. Arvores fazem exatamente isso.
#
# O que impedia era o EMPACOTAMENTO — tudo tem que ser constante dentro deste
# arquivo, porque `import` de arquivo separado depende do sys.path do
# container, a aposta que ja custou tres submissoes. 300 arvores nao cabem;
# 100 arvores rasas cabem em ~103 KB e sao percorridas por um interpretador de
# dez linhas, sem sklearn, sem numpy, sem import nenhum.
#
# Formato de cada no: (feature, limiar, filho_esq, filho_dir, valor).
# Folha tem feature = -1 e o valor no ultimo campo.
#
# Custo medido: 0,24 ms por decisao, contra 2.000 ms de orcamento (0,01%).
#
# Ligado por PTCG_ARVORES=1 ate passar no painel.
