# >>> ARVORES_FIM


def _nota_das_arvores(v) -> float:
    """Soma as folhas alcancadas por um vetor de features."""
    total = ARVORES_VIES
    for arv in ARVORES_PRIOR:
        no = 0
        while arv[no][0] >= 0:
            f, t, e, d, _ = arv[no]
            no = e if v[f] <= t else d
        total += arv[no][4]
    return total


def pontuar_com_prior(obs_dict) -> list[float] | None:
    """Nota de cada opcao pelo modelo aprendido. None se indisponivel.

    Ordena, nao decide: quem escolhe continua sendo a busca. Um prior que
    decide vira a L0 com passos extras, e a L0 e o gargalo medido — o agente
    perde 17% dos nocautes e 18% das vitorias que estao ao alcance.
    """
    if not PRIOR_PESOS or not W_PRIOR:
        return None
    try:
        vetores = features_da_decisao(obs_dict, _META_CARTA)
    except Exception:
        return None
    if not vetores:
        return None

    # GUARDA DE COMPRIMENTO. Sem ela, acrescentar uma feature ao vetor sem
    # retreinar levanta IndexError aqui — e o `except` la de cima do `agent()`
    # engole, matando em silencio o prior, que vale +10,11pp. O agente
    # continuaria jogando, so que pior, e nenhum teste acusaria.
    #
    # Devolver None e o comportamento certo: o chamador cai para a L0, que e
    # ruim mas honesta. Melhor perder o prior de forma visivel no painel do que
    # perder de forma invisivel.
    n = len(PRIOR_PESOS)
    if len(vetores[0]) != n:
        return None

    usar_arv = USAR_ARVORES and ARVORES_PRIOR and W_ARVORES
    notas = []
    for v in vetores:
        z = PRIOR_VIES
        for j in range(n):
            d = PRIOR_DESVIO[j]
            z += PRIOR_PESOS[j] * ((v[j] - PRIOR_MEDIA[j]) / d if d else 0.0)
        # A arvore SOMA a parte nao-linear, nao substitui a linear. A linear ja
        # vale +9,92pp medidos no painel; a arvore entra onde ela erra.
        if usar_arv:
            z += W_ARVORES * _nota_das_arvores(v)
        notas.append(z)
    return notas


def escolher_por_busca(obs_dict: dict, deck: list[int], prazo: float):
    """Avalia cada opcao 1 ply a frente. Devolve notas ou None se indisponivel.

    Devolve None — e o chamador cai para a L0 — sempre que o forward model nao
    puder ser usado: sem `search_begin_input`, sem `cg` real, ou erro do engine.
    Nunca levanta.
    """
    try:
        from cg.api import search_begin, search_end, search_step, to_observation_class
    except Exception:
        return None

    sel = (obs_dict or {}).get("select") or {}
    opcoes = sel.get("option") or []
    estado = (obs_dict or {}).get("current") or {}
    if not obs_dict.get("search_begin_input") or len(opcoes) < 2:
        return None
    if int(sel.get("maxCount", 1)) != 1 or int(sel.get("minCount", 1)) != 1:
        return None  # selecao multipla: o leque de combinacoes nao cabe em 1 ply

    eu = int(estado.get("yourIndex", 0))
    jogadores = estado.get("players") or []
    if len(jogadores) < 2:
        return None
    meu, dele = jogadores[eu] or {}, jogadores[1 - eu] or {}

    # Determinizacao. A versao anterior era `deck[i % len(deck)]` — a lista na
    # ORDEM DO ARQUIVO, ciclada. Isso nao e uma amostra do que resta: e sempre
    # o mesmo prefixo. Num deck como o do Ogerpon, cujas 18 energias estao no
    # fim do arquivo, a busca simulava um futuro quase sem energia e concluia
    # que anexar nao leva a nada. Medido: o agente termina a partida com 3,59
    # energias no ativo quando o modelo de compra preve 8,17.
    #
    # Aqui as cartas sao embaralhadas antes de serem distribuidas. Continua
    # ingenua — nao desconta o que ja esta visivel em campo, na mao e no
    # descarte — mas deixa de ser enviesada pela ordem do arquivo.
    ordem_estavel = os.environ.get("PTCG_DETERMINIZACAO") == "ordem"

    def _sorteador(cartas):
        """Distribui de um baralho embaralhado, sem repetir posicao."""
        baralho = list(cartas)
        random.shuffle(baralho)
        pos = [0]

        def puxar(qtd):
            qtd = int(qtd or 0)
            if qtd <= 0 or not baralho:
                return []
            saida = [baralho[(pos[0] + i) % len(baralho)] for i in range(qtd)]
            pos[0] = (pos[0] + qtd) % len(baralho)
            return saida
        return puxar

    def encher(qtd):
        qtd = int(qtd or 0)
        if qtd <= 0:
            return []
        return [deck[i % len(deck)] for i in range(qtd)]

    # O que EU nao vejo do meu proprio deck: minhas cartas, embaralhadas.
    meu_sorteio = encher if ordem_estavel else _sorteador(deck)

    # O que eu nao vejo do adversario: NAO sao as minhas cartas. Usar a minha
    # lista para o deck, os premios e a mao dele foi o erro que o 2 ply expos —
    # o turno inteiro dele passava a ser simulado com uma mao de fantasia. Aqui
    # sorteia-se um arquetipo do meta pela fatia de uso medida na ladder.
    if ordem_estavel or not META_PRIOR or not USAR_META_PRIOR:
        dele_sorteio = encher
    else:
        total = sum(u for u, _ in META_PRIOR)
        alvo = random.random() * total
        acumulado = 0.0
        escolhido = META_PRIOR[0][1]
        for peso, lista in META_PRIOR:
            acumulado += peso
            if alvo <= acumulado:
                escolhido = lista
                break
        dele_sorteio = _sorteador(escolhido)

    try:
        obs = to_observation_class(obs_dict)
        raiz = search_begin(
            obs,
            meu_sorteio(meu.get("deckCount")),
            meu_sorteio(len(meu.get("prize") or [])),
            dele_sorteio(dele.get("deckCount")),
            dele_sorteio(len(dele.get("prize") or [])),
            dele_sorteio(dele.get("handCount")),
            [],
            True,  # manual_coin: tira a variancia da moeda de dentro da busca
        )
    except Exception:
        return None

    notas = []
    try:
        if LARGURA_FEIXE > 0:
            notas = _expandir_feixe(search_step, raiz, len(opcoes), eu, prazo,
                                    LARGURA_FEIXE)
        else:
            for i in range(len(opcoes)):
                if time.time() > prazo:
                    return None  # watchdog: sem resultado parcial, cai para L0
                try:
                    prox = search_step(raiz.searchId, [i])
                    if AVALIAR_TURNO_INTEIRO:
                        prox = _rodar_ate_fim_do_turno(search_step, prox, eu, prazo)
                    if PLY >= 2:
                        prox = _rodar_turno_do_oponente(search_step, prox, eu, prazo)
                    notas.append(avaliar_estado(_campo(prox.observation, "current"), eu))
                except Exception:
                    notas.append(float("-inf"))  # opcao recusada nunca vence
    finally:
        try:
            search_end()
        except Exception:
            pass

    return notas if any(v != float("-inf") for v in notas) else None


def agent(obs_dict: dict) -> list[int]:
    """Funcao principal. SEMPRE retorna uma selecao legal dentro do tempo.

    PRIMEIRA CHAMADA: `select` vem None e o contrato exige devolver o DECK — os
    60 Card IDs. Nao e uma selecao de opcao; e a montagem da partida.

    Isso custou uma submissao (S1, 08/08, SubmissionStatus.ERROR): a arena local
    nunca exercita este caminho, porque `battle_start(deck0, deck1)` ja recebe os
    decks prontos. O contrato do container tem um passo que o harness local nao
    tem, e so a submissao revelou.
    """
    t0 = time.time()
    if (obs_dict or {}).get("select") is None:
        deck = MY_DECK or load_deck()
        return list(deck)

    sel = (obs_dict or {}).get("select", {}) or {}
    options = sel.get("option", []) or []
    min_count = int(sel.get("minCount", 1))
    max_count = int(sel.get("maxCount", 1))
    n = len(options)

    if n == 0:
        return []

    # Escada de degradacao, do melhor ao mais barato. Cada degrau tem saida
    # garantida: nenhuma jogada pode estourar o relogio, porque estourar = derrota.
    try:
        if time.time() - t0 > TIME_BUDGET_S:
            return select_indices([0.0] * n, min_count, max_count)

        # Degrau ZERO: se um ataque fecha a partida agora, ele nao precisa de
        # busca — precisa ser jogado. Vem antes de tudo porque a busca e
        # justamente quem perde essas: nos 15 casos perdidos medidos, ela nunca
        # pontuou 1e9 na opcao vencedora. Custa microssegundos.
        if USAR_VITORIA_IMEDIATA and min_count <= 1:
            i = vitoria_imediata(obs_dict)
            if i is not None:
                return [i]

        # Degrau ZERO-B: se o ativo morre no proximo turno e uma carta impede
        # isso, joga a carta. Vem antes da busca pelo mesmo motivo do degrau
        # acima — e uma conta fechada que nao depende do rollout — e e barata
        # de verdade: nem Item nem Ferramenta encerram o turno, entao o ataque
        # continua disponivel depois.
        if USAR_PROTECAO and min_count <= 1:
            i = proteger_do_nocaute(obs_dict)
            if i is not None:
                return [i]

        # L1c: busca conduzida ate o fim do turno. Cai para L0 sozinha se o
        # forward model nao estiver disponivel ou o orcamento apertar.
        if USAR_L1:
            notas = escolher_por_busca(obs_dict, MY_DECK, t0 + TIME_BUDGET_S)
            if notas is not None:
                return select_indices(notas, min_count, max_count)

        scores = score_options(options, obs_dict)
        return select_indices(scores, min_count, max_count)
    except Exception:
        # Fallback final: selecao legal minima (nunca travar / nunca invalida).
        return select_indices([0.0] * n, min_count, max_count)
